INSERT INTO habitats_presets VALUES ('tierra', 'Tierra (nivel del mar)', 21.0, 101.3, 14.7, 10.0, 1.0, '14,7 psi (101,3 kPa). Referencia de los ensayos estándar en 1 g.');
INSERT INTO habitats_presets VALUES ('iss', 'ISS / nave en tránsito', 21.0, 101.3, 14.7, 10.0, 0.0, 'Atmósfera similar a la Tierra en microgravedad (0 g) con ventilación forzada (~10 cm/s).');
INSERT INTO habitats_presets VALUES ('luna', 'Base lunar / rover presurizado', 30.0, 70.3, 10.2, 10.0, 0.167, 'Regla del enunciado: O2 de 30 % o más y presión de 10,2 psi (70,3 kPa) o menos.');
INSERT INTO habitats_presets VALUES ('rover', 'Rover lunar presurizado', 34.0, 56.5, 8.2, 10.0, 0.167, 'Atmósfera de rápida salida EVA (34% O2 a 8,2 psi / 56,5 kPa) en gravedad lunar (0,167 g).');
INSERT INTO habitats_presets VALUES ('marte', 'Hábitat en Marte', 26.5, 70.3, 10.2, 10.0, 0.38, 'Gravedad parcial marciana (0,38 g) con atmósfera enriquecida en O2 y presión reducida.');
INSERT INTO habitats_presets VALUES ('traje', 'Traje espacial (EVA)', 100.0, 29.6, 4.3, 15.0, 0.0, '100% O2 a 4,3 psi (29,6 kPa).');
INSERT INTO habitats_presets VALUES ('mina_tierra', 'Tierra: Mina Subterránea (Spinoff)', 20.9, 73.1, 10.6, 25.0, 1.0, 'Aplicación terrestre en faena minera en altura (~2750 m, Antofagasta): discriminación óptica humo vs polvo (SAME/DAFT).');
