INSERT INTO investigations VALUES ('bass', 'BASS', 'Burning and Suppression of Solids', 'BASS', '{"prevencion", "supresion"}', 5, 'solido', '{"SIBAL (algodón-fibra de vidrio)", "Nomex", "Ultem", "PMMA (acrílico)", "fibra de vidrio con cera", "velas de parafina"}', 17.0, 21.0, 'medido', 101.3, 101.3, 'cabina', 1.0, 40.0, 'medido', 0.0, 'ISS', 'MSG', 'Ducto de flujo SPICE modificado (sección de 76 x 76 mm)', '2012', 'si', 'Comprobar si los materiales arden igual o mejor en microgravedad con ventilación adecuada; estudiar combustión y extinción; orientar estrategias de extinción.', 'Material, geometría, velocidad de flujo y caudal de nitrógeno supresor (0-500 cc/min, aumentado hasta extinguir).', '{"video", "fotografía", "anemómetro", "radiómetro"}', '{"id": "bass", "acronym": "BASS", "name": "Burning and Suppression of Solids", "family": "BASS", "pillars": ["prevencion", "supresion"], "directness": 5, "directness_reason": "Nombrada en el enunciado como estudio directo de inflamabilidad de sólidos.", "fuel_phase": "solido", "fuels": ["SIBAL (algodón-fibra de vidrio)", "Nomex", "Ultem", "PMMA (acrílico)", "fibra de vidrio con cera", "velas de parafina"], "geometry": "41 muestras. Láminas delgadas 12 cm x 1-2 cm; láminas gruesas 5 x 1 cm, 1-2 mm de espesor; esferas de PMMA de 1 y 2 cm; velas de 6 mm x 25 mm.", "o2": {"min": 17.0, "max": 21.0, "basis": "medido", "note": "Aire ISS (21%) diluido con N2 hasta 17% en MSG (ISS Guide p.19-20)."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "Presión nominal de trabajo en MSG (1 atm / 101.3 kPa)."}, "flow": {"min": 1.0, "max": 40.0, "basis": "medido", "note": "Escalones de 40 cm/s a <1 cm/s en flujo opuesto y concurrente (PSI-26 / ISS Guide p.20)."}, "gravity": 0.0, "platform": "ISS", "facility": "MSG", "hardware": "Ducto de flujo SPICE modificado (sección de 76 x 76 mm)", "years": "2012", "objectives": "Comprobar si los materiales arden igual o mejor en microgravedad con ventilación adecuada; estudiar combustión y extinción; orientar estrategias de extinción.", "variables": "Material, geometría, velocidad de flujo y caudal de nitrógeno supresor (0-500 cc/min, aumentado hasta extinguir).", "diagnostics": ["video", "fotografía", "anemómetro", "radiómetro"], "findings": [], "pi": "Olson, Ferkul, Takahashi, T''ien (según PSI)", "in_psi": "si", "sources": ["psi_26", "fs_bass", "challenge"], "psi": {"id": "PSI-26", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-26", "project_start": "10-01-2009", "project_end": "06-30-2013", "platform": "International Space Station (ISS)", "hardware": "Microgravity Science Glovebox", "keywords": ["Flame Spread", "Fire suppression system", "Damkohler number", "Boundary layer", "Fire safety", "Forced Flow Flame", "Kinetic regime"], "reused_by": ["PSI-62"]}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO investigations VALUES ('bass2', 'BASS-II', 'Burning and Suppression of Solids - II', 'BASS', '{"prevencion", "supresion"}', 5, 'solido', '{"PMMA (varillas, láminas, placas, esfera)", "SIBAL (algodón-fibra de vidrio)"}', 15.0, 21.0, 'medido', 101.3, 101.3, 'cabina', 0.0, 55.0, 'medido', 0.0, 'ISS', 'MSG', 'Ducto de flujo SPICE modificado (76 x 76 mm)', '2014', 'si', 'Hallar el O2 mínimo o la velocidad de flujo mínima para que un material arda, y compararlos con los límites de propagación ascendente en la Tierra, para guiar la selección de materiales.', 'Concentración de O2, velocidad de ventilación, tipo de combustible, espesor y geometría.', '{"video con datos superpuestos", "cámara fotográfica", "anemómetro", "radiómetro", "O2 y CO (CSA-CP)", "monitor de CO2"}', '{"id": "bass2", "acronym": "BASS-II", "name": "Burning and Suppression of Solids - II", "family": "BASS", "pillars": ["prevencion", "supresion"], "directness": 5, "directness_reason": "Nombrada en el enunciado; mide límites de inflamabilidad de sólidos variando O2 y flujo.", "fuel_phase": "solido", "fuels": ["PMMA (varillas, láminas, placas, esfera)", "SIBAL (algodón-fibra de vidrio)"], "geometry": "100 muestras. Láminas de 10 cm x 1-2 cm, espesores 1-5 mm; varillas de PMMA de 6,3 / 9,5 / 12,7 mm de diámetro; sección de esfera.", "o2": {"min": 15.0, "max": 21.0, "basis": "medido", "note": "Se redujo el O2 diluyendo el volumen de trabajo del MSG con N2."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "Presión estándar MSG en la ISS (101.3 kPa / 14.7 psi)."}, "flow": {"min": 0.0, "max": 55.0, "basis": "medido", "note": "Flujo opuesto y concurrente. Varillas de PMMA en flujo opuesto: 0,4-8 cm/s. La ficha de PSI indica velocidades de hasta 40 cm/s; el rango 0-55 cm/s viene del informe en NTRS."}, "gravity": 0.0, "platform": "ISS", "facility": "MSG", "hardware": "Ducto de flujo SPICE modificado (76 x 76 mm)", "years": "2014", "objectives": "Hallar el O2 mínimo o la velocidad de flujo mínima para que un material arda, y compararlos con los límites de propagación ascendente en la Tierra, para guiar la selección de materiales.", "variables": "Concentración de O2, velocidad de ventilación, tipo de combustible, espesor y geometría.", "diagnostics": ["video con datos superpuestos", "cámara fotográfica", "anemómetro", "radiómetro", "O2 y CO (CSA-CP)", "monitor de CO2"], "findings": [{"text": "Los materiales pueden arder con menor concentración de O2 en microgravedad que en gravedad normal.", "source": "bass2_limits"}, {"text": "En varillas de PMMA la llama se sostuvo con 17% de O2 en microgravedad frente a 18% en 1 g, y se propago más rápido.", "source": "bass2_pmma"}, {"text": "Las llamas siempre se apagaron al detener el ventilador: cortar la ventilación es una buena primera defensa en la ISS.", "source": "bass2_limits"}, {"text": "A alta velocidad la llama se desprende (blowoff); a muy baja (<1 cm/s) puede sostenerse azul, tenue y estable.", "source": "bass2_results"}, {"text": "La mayoría de los ensayos libero menos de 100 W.", "source": "bass2_summary"}, {"text": "Los modelos sobreestiman las velocidades de propagación.", "source": "fs_bass"}], "pi": "Ferkul, Fernandez-Pello, Miller, T''ien, Bhattachjee (según PSI)", "in_psi": "si", "sources": ["psi_25", "fs_bass", "bass2_summary", "bass2_results", "bass2_pmma", "bass2_limits", "challenge"], "psi": {"id": "PSI-25", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-25", "project_start": "01-01-2010", "project_end": "12-31-2022", "platform": "International Space Station (ISS)", "hardware": "Microgravity Science Glovebox (MSG)", "keywords": ["Flame Spread", "extinction limits", "MSG", "Fire Suppression", "Solid Fuels", "Forced Flow Velocity", "BASS", "Fire Safety"], "reused_by": ["PSI-62"]}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:BASS-II#1', 'bass2', 'BASS-II', 'finding', 'Los materiales pueden arder con menor concentración de O2 en microgravedad que en gravedad normal.', 'bass2_limits');
INSERT INTO knowledge_chunks VALUES ('psi:BASS-II#2', 'bass2', 'BASS-II', 'finding', 'En varillas de PMMA la llama se sostuvo con 17% de O2 en microgravedad frente a 18% en 1 g, y se propago más rápido.', 'bass2_pmma');
INSERT INTO knowledge_chunks VALUES ('psi:BASS-II#3', 'bass2', 'BASS-II', 'finding', 'Las llamas siempre se apagaron al detener el ventilador: cortar la ventilación es una buena primera defensa en la ISS.', 'bass2_limits');
INSERT INTO knowledge_chunks VALUES ('psi:BASS-II#4', 'bass2', 'BASS-II', 'finding', 'A alta velocidad la llama se desprende (blowoff); a muy baja (<1 cm/s) puede sostenerse azul, tenue y estable.', 'bass2_results');
INSERT INTO knowledge_chunks VALUES ('psi:BASS-II#5', 'bass2', 'BASS-II', 'finding', 'La mayoría de los ensayos libero menos de 100 W.', 'bass2_summary');
INSERT INTO knowledge_chunks VALUES ('psi:BASS-II#6', 'bass2', 'BASS-II', 'finding', 'Los modelos sobreestiman las velocidades de propagación.', 'fs_bass');
INSERT INTO investigations VALUES ('saffire1', 'Saffire-I', 'Spacecraft Fire Safety Demonstration I', 'Saffire', '{"prevencion"}', 5, 'solido', '{"SIBAL (algodón-fibra de vidrio)"}', 21.7, 21.7, 'medido', 101.3, 101.3, 'medido', 20.0, 20.0, 'medido', 0.0, 'Cygnus (tras desacoplarse de la ISS)', 'Saffire Flow Unit', 'Ducto de flujo + bahía de aviónica (~0,5 x 1 x 1,3 m)', '2016', 'si', 'Investigar el crecimiento de llama a gran escala y los límites de inflamabilidad de materiales en el espacio.', 'Ensayo único: muestra grande, ignición por alambre caliente.', '{"termopares (flujo, llama y pluma)", "dos radiómetros", "sensores de presión, CO2 y O2", "dos anemómetros"}', '{"id": "saffire1", "acronym": "Saffire-I", "name": "Spacecraft Fire Safety Demonstration I", "family": "Saffire", "pillars": ["prevencion"], "directness": 5, "directness_reason": "Nombrada en el enunciado; fuego a gran escala en una nave real.", "fuel_phase": "solido", "fuels": ["SIBAL (algodón-fibra de vidrio)"], "geometry": "Una muestra de 0,4 m x 0,94 m, al menos un orden de magnitud mayor que cualquier ensayo previo en baja gravedad.", "o2": {"min": 21.7, "max": 21.7, "basis": "medido", "note": "Concentración inicial (lectura de la ISS). Fuente: Ferkul et al. 2017, pág. 14; también Han et al. 2026, tabla 1, pág. 2."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "medido", "note": "1 atm según Han et al. 2026, tabla 1, pág. 2."}, "flow": {"min": 20.0, "max": 20.0, "basis": "medido", "note": "Fuente: ficha de PSI (PSI-98)."}, "gravity": 0.0, "platform": "Cygnus (tras desacoplarse de la ISS)", "facility": "Saffire Flow Unit", "hardware": "Ducto de flujo + bahía de aviónica (~0,5 x 1 x 1,3 m)", "years": "2016", "objectives": "Investigar el crecimiento de llama a gran escala y los límites de inflamabilidad de materiales en el espacio.", "variables": "Ensayo único: muestra grande, ignición por alambre caliente.", "diagnostics": ["termopares (flujo, llama y pluma)", "dos radiómetros", "sensores de presión, CO2 y O2", "dos anemómetros"], "findings": [{"text": "Cuando la llama alcanza su tamaño límite, las llamas aguas abajo se inhiben o apagan por la ''sombra de oxígeno'' de la llama aguas arriba.", "source": "saffire_2021"}, {"text": "En el ensayo concurrente con la muestra grande de SIBAL (40,6 x 94 cm) a 20 cm/s, la llama avanzó en promedio 1,8 mm/s, con una potencia estimada de 1200 ± 300 W y 420 s de combustión.", "source": "p_ferkul2017", "page": 17}, {"text": "Al apagarse el flujo de aire al final del tiempo asignado, la llama se extinguió de inmediato.", "source": "p_ferkul2017", "page": 16}, {"text": "En flujo opuesto la llama avanzó más lento que en flujo concurrente: 1,3 mm/s frente a 1,8 mm/s, con una longitud de llama de unos 24 mm frente a unos 40 mm.", "source": "p_ferkul2017", "page": 21}, {"text": "A diferencia de lo que ocurre en 1 g, se logró una llama estable incluso en una muestra ancha en flujo concurrente; las llamas avanzaron más lento que en ensayos previos en ductos más pequeños, lo que muestra la importancia de los espacios confinados.", "source": "p_ferkul2017", "page": 26}], "pi": "Urban (según PSI)", "in_psi": "si", "sources": ["psi_98", "fs_saffire", "saffire_design", "saffire_2021", "challenge", "p_ferkul2017"], "psi": {"id": "PSI-98", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-98", "project_start": "03-02-2001", "project_end": "02-28-2008", "platform": "International Space Station (ISS)", "hardware": "Saffire 1 enclosure in Cygnus", "keywords": ["Cygnus", "SAFFIRE", "Flame Spread", "Surface Combustion", "Fire Safety", "Fire", "Oxidizer flux", "Solid burning rate", "Smoldering"], "reused_by": []}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-I#1', 'saffire1', 'Saffire-I', 'finding', 'Cuando la llama alcanza su tamaño límite, las llamas aguas abajo se inhiben o apagan por la ''sombra de oxígeno'' de la llama aguas arriba.', 'saffire_2021');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-I#2', 'saffire1', 'Saffire-I', 'finding', 'En el ensayo concurrente con la muestra grande de SIBAL (40,6 x 94 cm) a 20 cm/s, la llama avanzó en promedio 1,8 mm/s, con una potencia estimada de 1200 ± 300 W y 420 s de combustión.', 'p_ferkul2017');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-I#3', 'saffire1', 'Saffire-I', 'finding', 'Al apagarse el flujo de aire al final del tiempo asignado, la llama se extinguió de inmediato.', 'p_ferkul2017');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-I#4', 'saffire1', 'Saffire-I', 'finding', 'En flujo opuesto la llama avanzó más lento que en flujo concurrente: 1,3 mm/s frente a 1,8 mm/s, con una longitud de llama de unos 24 mm frente a unos 40 mm.', 'p_ferkul2017');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-I#5', 'saffire1', 'Saffire-I', 'finding', 'A diferencia de lo que ocurre en 1 g, se logró una llama estable incluso en una muestra ancha en flujo concurrente; las llamas avanzaron más lento que en ensayos previos en ductos más pequeños, lo que muestra la importancia de los espacios confinados.', 'p_ferkul2017');
INSERT INTO investigations VALUES ('saffire2', 'Saffire-II', 'Spacecraft Fire Safety Demonstration II', 'Saffire', '{"prevencion"}', 5, 'solido', '{"silicona (láminas de 0,27 a 1,03 mm)", "SIBAL (algodón-fibra de vidrio)", "PMMA delgado + Nomex (muestra compuesta)", "PMMA de 1 cm"}', 22.1, 22.1, 'medido', 101.3, 101.3, 'medido', 20.0, 25.0, 'medido', 0.0, 'Cygnus', 'Saffire Flow Unit', 'Saffire Flow Unit', '2016', 'si', 'Ampliar los datos de Saffire-I con nuevos materiales.', 'Material (nueve muestras).', '{"termopares (flujo, llama y pluma)", "dos radiómetros", "sensores de presión, CO2 y O2", "dos anemómetros"}', '{"id": "saffire2", "acronym": "Saffire-II", "name": "Spacecraft Fire Safety Demonstration II", "family": "Saffire", "pillars": ["prevencion"], "directness": 5, "directness_reason": "Nombrada en el enunciado; compara materiales reales de nave.", "fuel_phase": "solido", "fuels": ["silicona (láminas de 0,27 a 1,03 mm)", "SIBAL (algodón-fibra de vidrio)", "PMMA delgado + Nomex (muestra compuesta)", "PMMA de 1 cm"], "geometry": "Nueve muestras de 5 cm x 29 cm en una misma tarjeta.", "o2": {"min": 22.1, "max": 22.1, "basis": "medido", "note": "Concentración inicial (lectura de la ISS). Fuente: Ferkul et al. 2017, pág. 9."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "medido", "note": "1 atm según Han et al. 2026, tabla 1, pág. 2."}, "flow": {"min": 20.0, "max": 25.0, "basis": "medido", "note": "20 cm/s en todas las muestras salvo la 2-6 (25 cm/s), según Ferkul et al. 2017, pág. 9, y Han et al. 2026, pág. 2. La ficha de PSI (PSI-99) indica 20 o 30 cm/s: hay una discrepancia entre fuentes."}, "gravity": 0.0, "platform": "Cygnus", "facility": "Saffire Flow Unit", "hardware": "Saffire Flow Unit", "years": "2016", "objectives": "Ampliar los datos de Saffire-I con nuevos materiales.", "variables": "Material (nueve muestras).", "diagnostics": ["termopares (flujo, llama y pluma)", "dos radiómetros", "sensores de presión, CO2 y O2", "dos anemómetros"], "findings": [{"text": "Ninguna de las muestras de silicona ardió en microgravedad, aunque la más delgada se consume por completo en los ensayos de propagación ascendente en 1 g.", "source": "p_ferkul2017", "page": 12}, {"text": "El Nomex, un tejido común en la ISS calificado como seguro, no se encendió ni siquiera bañado por la llama piloto de una muestra de PMMA.", "source": "p_ferkul2017", "page": 26}, {"text": "Con muestras de SIBAL de 5 cm de ancho, la llama avanzó 2,1 mm/s a 20 cm/s y 2,6 mm/s a 25 cm/s.", "source": "p_ferkul2017", "page": 29}], "pi": "Urban, Ruff (según PSI)", "in_psi": "si", "sources": ["psi_99", "fs_saffire", "challenge", "p_ferkul2017"], "psi": {"id": "PSI-99", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-99", "project_start": "09-30-2016", "project_end": "04-01-2017", "platform": "Cygnus Spacecraft", "hardware": "Cygnus Pressurized Cargo Module; SAFFIRE", "keywords": ["fire", "Cygnus", "SAFFIRE", "Smoldering", "fire safety", "Nomex", "SHS", "Smoke Distribution"], "reused_by": []}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-II#1', 'saffire2', 'Saffire-II', 'finding', 'Ninguna de las muestras de silicona ardió en microgravedad, aunque la más delgada se consume por completo en los ensayos de propagación ascendente en 1 g.', 'p_ferkul2017');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-II#2', 'saffire2', 'Saffire-II', 'finding', 'El Nomex, un tejido común en la ISS calificado como seguro, no se encendió ni siquiera bañado por la llama piloto de una muestra de PMMA.', 'p_ferkul2017');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-II#3', 'saffire2', 'Saffire-II', 'finding', 'Con muestras de SIBAL de 5 cm de ancho, la llama avanzó 2,1 mm/s a 20 cm/s y 2,6 mm/s a 25 cm/s.', 'p_ferkul2017');
INSERT INTO investigations VALUES ('saffire3', 'Saffire-III', 'Spacecraft Fire Safety Demonstration III', 'Saffire', '{"prevencion"}', 5, 'solido', '{"SIBAL (algodón-fibra de vidrio)"}', 21.2, 21.2, 'medido', 101.3, 101.3, 'medido', 30.0, 30.0, 'medido', 0.0, 'Cygnus', 'Saffire Flow Unit', 'Saffire Flow Unit', '2017', 'si', 'Repetir el material de Saffire-I con mayor velocidad de flujo.', 'Velocidad de flujo respecto de Saffire-I.', '{"termopares (flujo, llama y pluma)", "dos radiómetros", "sensores de presión, CO2 y O2", "dos anemómetros"}', '{"id": "saffire3", "acronym": "Saffire-III", "name": "Spacecraft Fire Safety Demonstration III", "family": "Saffire", "pillars": ["prevencion"], "directness": 5, "directness_reason": "Nombrada en el enunciado; efecto del flujo de aire a gran escala.", "fuel_phase": "solido", "fuels": ["SIBAL (algodón-fibra de vidrio)"], "geometry": "Una muestra de 0,4 m x 0,94 m (igual que Saffire-I).", "o2": {"min": 21.2, "max": 21.2, "basis": "medido", "note": "Fuente: Han et al. 2026, tabla 1, pág. 2."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "medido", "note": "1 atm según Han et al. 2026, tabla 1, pág. 2."}, "flow": {"min": 30.0, "max": 30.0, "basis": "medido", "note": "30 cm/s, frente a 20 cm/s en Saffire-I. Fuente: ficha de PSI (PSI-100). Han et al. 2026 (tabla 1, pág. 2) indica 25 cm/s: hay una discrepancia entre fuentes."}, "gravity": 0.0, "platform": "Cygnus", "facility": "Saffire Flow Unit", "hardware": "Saffire Flow Unit", "years": "2017", "objectives": "Repetir el material de Saffire-I con mayor velocidad de flujo.", "variables": "Velocidad de flujo respecto de Saffire-I.", "diagnostics": ["termopares (flujo, llama y pluma)", "dos radiómetros", "sensores de presión, CO2 y O2", "dos anemómetros"], "findings": [], "pi": "Urban (según PSI)", "in_psi": "si", "sources": ["psi_100", "fs_saffire", "saffire_design", "challenge"], "psi": {"id": "PSI-100", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-100", "project_start": "04-18-2017", "project_end": null, "platform": "International Space Station (ISS)", "hardware": "Saffire III enclosure in Cygnus", "keywords": ["SAFFIRE", "Fire Safety", "Surface Combustion", "Smoldering", "Flame Spread", "low-gravity fire testing", "flammability"], "reused_by": []}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "medido"}}'::jsonb);
INSERT INTO investigations VALUES ('saffire4', 'Saffire-IV', 'Spacecraft Fire Safety Demonstration IV', 'Saffire', '{"prevencion", "deteccion"}', 5, 'solido', '{"SIBAL (algodón-fibra de vidrio)", "Nomex", "PMMA"}', 22.0, 22.0, 'medido', 100.0, 100.0, 'medido', 20.0, 20.0, 'medido', 0.0, 'Cygnus (NG-13)', 'Saffire Flow Unit', 'Saffire Flow Unit con cámaras laterales, sensores de gas y Far Field Diagnostics', '2020', 'no', 'Comparar los materiales de Saffire-II en otras condiciones y medir el impacto del fuego sobre la nave (gases, humo, temperatura).', 'Material, altura de ducto.', '{"video", "termopares", "radiómetros", "calorimetría por consumo de O2", "CO2/CO distribuidos", "sensores remotos de partículas"}', '{"id": "saffire4", "acronym": "Saffire-IV", "name": "Spacecraft Fire Safety Demonstration IV", "family": "Saffire", "pillars": ["prevencion", "deteccion"], "directness": 5, "directness_reason": "Fuego a gran escala más transporte de humo y gases en la nave.", "fuel_phase": "solido", "fuels": ["SIBAL (algodón-fibra de vidrio)", "Nomex", "PMMA"], "geometry": "Muestras de 40 cm de ancho; tela SIBAL de 50 cm de largo. Ducto más bajo que en Saffire-I.", "o2": {"min": 22.0, "max": 22.0, "basis": "medido"}, "pressure": {"min": 100.0, "max": 100.0, "basis": "medido"}, "flow": {"min": 20.0, "max": 20.0, "basis": "medido", "note": "Concurrente."}, "gravity": 0.0, "platform": "Cygnus (NG-13)", "facility": "Saffire Flow Unit", "hardware": "Saffire Flow Unit con cámaras laterales, sensores de gas y Far Field Diagnostics", "years": "2020", "objectives": "Comparar los materiales de Saffire-II en otras condiciones y medir el impacto del fuego sobre la nave (gases, humo, temperatura).", "variables": "Material, altura de ducto.", "diagnostics": ["video", "termopares", "radiómetros", "calorimetría por consumo de O2", "CO2/CO distribuidos", "sensores remotos de partículas"], "findings": [{"text": "El tamaño del ducto y el desarrollo del flujo afectan la velocidad de propagación y la longitud de pirólisis.", "source": "saffire_2021"}, {"text": "Pese a liberaciones de calor de hasta 10 kW, las condiciones promedio de la nave no llegaron a niveles inaceptables.", "source": "saffire_2021"}], "pi": "David Urban, Gary Ruff", "in_psi": "no", "sources": ["fs_saffire", "saffire_2021", "saffire_2024"], "psi": null, "pressure_psi": {"min": 14.5, "max": 14.5, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-IV#1', 'saffire4', 'Saffire-IV', 'finding', 'El tamaño del ducto y el desarrollo del flujo afectan la velocidad de propagación y la longitud de pirólisis.', 'saffire_2021');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-IV#2', 'saffire4', 'Saffire-IV', 'finding', 'Pese a liberaciones de calor de hasta 10 kW, las condiciones promedio de la nave no llegaron a niveles inaceptables.', 'saffire_2021');
INSERT INTO investigations VALUES ('saffire5', 'Saffire-V', 'Spacecraft Fire Safety Demonstration V', 'Saffire', '{"prevencion", "deteccion"}', 5, 'solido', '{"algodón (jersey)", "PMMA estructurado"}', 25.4, 26.2, 'medido', 70.7, 72.6, 'medido', 20.0, 20.0, 'medido', 0.0, 'Cygnus', 'Saffire Flow Unit', 'Saffire Flow Unit + Far Field Diagnostics', '2021', 'no', 'Examinar el crecimiento del fuego a las presiones y concentraciones de oxígeno esperadas en futuras naves de exploración.', 'Atmósfera (O2 y presión), material, flujo.', '{"video", "termopares", "radiómetros", "calorimetría por consumo de O2", "CO2/CO distribuidos"}', '{"id": "saffire5", "acronym": "Saffire-V", "name": "Spacecraft Fire Safety Demonstration V", "family": "Saffire", "pillars": ["prevencion", "deteccion"], "directness": 5, "directness_reason": "Primer fuego a gran escala en atmósfera de exploración (más O2, menos presión).", "fuel_phase": "solido", "fuels": ["algodón (jersey)", "PMMA estructurado"], "geometry": "Tela de algodón de 50 cm de largo; muestra gruesa de PMMA estructurado.", "o2": {"min": 25.4, "max": 26.2, "basis": "medido"}, "pressure": {"min": 70.7, "max": 72.6, "basis": "medido"}, "flow": {"min": 20.0, "max": 20.0, "basis": "medido", "note": "Concurrente; en un ensayo se redujo y se corto el flujo."}, "gravity": 0.0, "platform": "Cygnus", "facility": "Saffire Flow Unit", "hardware": "Saffire Flow Unit + Far Field Diagnostics", "years": "2021", "objectives": "Examinar el crecimiento del fuego a las presiones y concentraciones de oxígeno esperadas en futuras naves de exploración.", "variables": "Atmósfera (O2 y presión), material, flujo.", "diagnostics": ["video", "termopares", "radiómetros", "calorimetría por consumo de O2", "CO2/CO distribuidos"], "findings": [{"text": "Con O2 elevado no se puede asumir que un combustible delgado que carboniza se apague rápido al cortar el flujo.", "source": "saffire_2021"}, {"text": "El aumento de CO2 y CO en la nave fue más significativo que el de temperatura y presión.", "source": "saffire_2024"}], "pi": "David Urban, Gary Ruff", "in_psi": "no", "sources": ["fs_saffire", "saffire_2021", "saffire_2024"], "psi": null, "pressure_psi": {"min": 10.3, "max": 10.5, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-V#1', 'saffire5', 'Saffire-V', 'finding', 'Con O2 elevado no se puede asumir que un combustible delgado que carboniza se apague rápido al cortar el flujo.', 'saffire_2021');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-V#2', 'saffire5', 'Saffire-V', 'finding', 'El aumento de CO2 y CO en la nave fue más significativo que el de temperatura y presión.', 'saffire_2024');
INSERT INTO investigations VALUES ('saffire6', 'Saffire-VI', 'Spacecraft Fire Safety Demonstration VI', 'Saffire', '{"prevencion", "deteccion", "supresion"}', 5, 'solido', '{"SIBAL (algodón-fibra de vidrio)", "PMMA de 1 cm (dos caras)", "PMMA de 0,5 cm (una cara)", "Nomex (7 cm)"}', 28.8, 31.0, 'medido', 54.1, 55.2, 'medido', 5.0, 20.0, 'medido', 0.0, 'Cygnus', 'Saffire Flow Unit', 'Saffire Flow Unit + Far Field Diagnostics', '2023', 'no', 'Probar la inflamabilidad a distintos niveles de oxígeno y demostrar detección de incendios, monitoreo de productos de combustión y limpieza posterior.', 'Atmósfera (O2 y presión), material, espesor, flujo.', '{"video", "calorimetría por consumo de O2", "CO2/CO", "detector de humo por ionización (campo lejano)", "material particulado"}', '{"id": "saffire6", "acronym": "Saffire-VI", "name": "Spacecraft Fire Safety Demonstration VI", "family": "Saffire", "pillars": ["prevencion", "deteccion", "supresion"], "directness": 5, "directness_reason": "El ensayo de sólidos más cercano a la atmósfera de la base lunar; incluye detección y limpieza post-incendio.", "fuel_phase": "solido", "fuels": ["SIBAL (algodón-fibra de vidrio)", "PMMA de 1 cm (dos caras)", "PMMA de 0,5 cm (una cara)", "Nomex (7 cm)"], "geometry": "Muestras de 41 cm de ancho: tela SIBAL de 50 cm; PMMA de 1 cm (dos caras) y de 0,5 cm (una cara), de 18 cm; Nomex de 7 cm. Ducto de 45 cm de ancho y 109 cm de largo.", "o2": {"min": 28.8, "max": 31.0, "basis": "medido"}, "pressure": {"min": 54.1, "max": 55.2, "basis": "medido"}, "flow": {"min": 5.0, "max": 20.0, "basis": "medido", "note": "Concurrente a 20 cm/s; reducido a 5 cm/s y luego cortado en un ensayo."}, "gravity": 0.0, "platform": "Cygnus", "facility": "Saffire Flow Unit", "hardware": "Saffire Flow Unit + Far Field Diagnostics", "years": "2023", "objectives": "Probar la inflamabilidad a distintos niveles de oxígeno y demostrar detección de incendios, monitoreo de productos de combustión y limpieza posterior.", "variables": "Atmósfera (O2 y presión), material, espesor, flujo.", "diagnostics": ["video", "calorimetría por consumo de O2", "CO2/CO", "detector de humo por ionización (campo lejano)", "material particulado"], "findings": [{"text": "Incendios de 1,5 a 3,2 kW en naves sin tripulación de 17 a 19 m³: la temperatura solo subió de forma importante muy cerca del fuego, pero el CO y el CO2 del ambiente subieron mucho, y en los ensayos con PMMA superaron el límite de CO2 para 1 hora y el de CO para 24 horas.", "source": "p_urban2024", "page": 6}, {"text": "El humo fue detectado por un detector de ionización y por un sistema de dispersión de luz, pero un umbral de alarma típico solo se alcanzó a los 981 s, cuando ya había ocurrido la mayor parte de la liberación de gases peligrosos.", "source": "p_urban2024", "page": 6}, {"text": "Como en los incendios terrestres, el principal peligro para la tripulación no es el calor sino el humo y los gases de combustión.", "source": "p_urban2024", "page": 6}, {"text": "La llama sobre SIBAL avanzó más rápido en Saffire VI que en Saffire IV, aunque un modelo previo predecía lo contrario por la menor presión parcial de oxígeno.", "source": "p_han2026", "page": 2}], "pi": "David Urban, Gary Ruff", "in_psi": "no", "sources": ["fs_saffire", "saffire_2024", "p_urban2024", "p_han2026"], "psi": null, "pressure_psi": {"min": 7.8, "max": 8.0, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-VI#1', 'saffire6', 'Saffire-VI', 'finding', 'Incendios de 1,5 a 3,2 kW en naves sin tripulación de 17 a 19 m³: la temperatura solo subió de forma importante muy cerca del fuego, pero el CO y el CO2 del ambiente subieron mucho, y en los ensayos con PMMA superaron el límite de CO2 para 1 hora y el de CO para 24 horas.', 'p_urban2024');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-VI#2', 'saffire6', 'Saffire-VI', 'finding', 'El humo fue detectado por un detector de ionización y por un sistema de dispersión de luz, pero un umbral de alarma típico solo se alcanzó a los 981 s, cuando ya había ocurrido la mayor parte de la liberación de gases peligrosos.', 'p_urban2024');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-VI#3', 'saffire6', 'Saffire-VI', 'finding', 'Como en los incendios terrestres, el principal peligro para la tripulación no es el calor sino el humo y los gases de combustión.', 'p_urban2024');
INSERT INTO knowledge_chunks VALUES ('psi:Saffire-VI#4', 'saffire6', 'Saffire-VI', 'finding', 'La llama sobre SIBAL avanzó más rápido en Saffire VI que en Saffire IV, aunque un modelo previo predecía lo contrario por la menor presión parcial de oxígeno.', 'p_han2026');
INSERT INTO investigations VALUES ('same', 'SAME', 'Smoke Aerosol Measurement Experiment', 'SAME', '{"deteccion"}', 5, 'aerosol', '{"Teflon", "Kapton", "celulosa", "goma de silicona", "dibutil-ftalato en mecha porosa"}', 21.0, 21.0, 'cabina', 101.3, 101.3, 'cabina', 5.0, 20.0, 'planificado', 0.0, 'ISS (Expedición 15)', 'MSG', 'Hardware SAME', '2007', 'si', 'Medir tamaño y distribución de partículas de humo de materiales de nave en microgravedad y evaluar detectores por ionización (Shuttle) y fotoelectricos (ISS).', 'Material, caudal de aire, temperatura de calentamiento y tiempo de envejecimiento del humo.', '{"contador de partículas", "detector por ionización", "detector por dispersión de luz", "momentos de la distribución de tamaños", "DustTrak"}', '{"id": "same", "acronym": "SAME", "name": "Smoke Aerosol Measurement Experiment", "family": "SAME", "pillars": ["deteccion"], "directness": 5, "directness_reason": "Nombrada en el enunciado como el estudio de detección de incendios.", "fuel_phase": "aerosol", "fuels": ["Teflon", "Kapton", "celulosa", "goma de silicona", "dibutil-ftalato en mecha porosa"], "geometry": "30 muestras (seis por material) sobrecalentadas para generar humo, sin llama.", "o2": {"min": 21.0, "max": 21.0, "basis": "cabina", "note": "Aire estándar ISS dentro de MSG."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "101.3 kPa en MSG."}, "flow": {"min": 5.0, "max": 20.0, "basis": "planificado", "note": "Caudal de aire variado en ducto de envejecimiento de humo."}, "gravity": 0.0, "platform": "ISS (Expedición 15)", "facility": "MSG", "hardware": "Hardware SAME", "years": "2007", "objectives": "Medir tamaño y distribución de partículas de humo de materiales de nave en microgravedad y evaluar detectores por ionización (Shuttle) y fotoelectricos (ISS).", "variables": "Material, caudal de aire, temperatura de calentamiento y tiempo de envejecimiento del humo.", "diagnostics": ["contador de partículas", "detector por ionización", "detector por dispersión de luz", "momentos de la distribución de tamaños", "DustTrak"], "findings": [{"text": "Los diámetros medios aritméticos estuvieron en el rango de 100 a 200 nm.", "source": "fs_same"}, {"text": "Goma de silicona: diámetro medio de 227 nm, pero casi la mitad de la masa en partículas mayores de 1000 nm.", "source": "fs_same"}, {"text": "Al envejecer, baja mucho el número de partículas y la masa se mantiene: coagulación.", "source": "fs_same"}, {"text": "Todas las muestras generaron muchas partículas submicrónicas, que un detector por ionización capta mejor; el de dispersión de luz funciono bien en la mayoría de los casos.", "source": "fs_same"}], "pi": "Urban, Mulholland, Fortenberry, Cleary, Yang (según PSI)", "in_psi": "si", "sources": ["psi_102", "fs_same", "challenge"], "psi": {"id": "PSI-102", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-102", "project_start": "03-02-2001", "project_end": "02-28-2008", "platform": "International Space Station (ISS)", "hardware": "Comparitive Soot Diagnostic Hardware", "keywords": ["Smoke", "Surface Combustion", "Fire Safety", "Bio-Astronautics", "Smoldering"], "reused_by": ["PSI-115"]}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:SAME#1', 'same', 'SAME', 'finding', 'Los diámetros medios aritméticos estuvieron en el rango de 100 a 200 nm.', 'fs_same');
INSERT INTO knowledge_chunks VALUES ('psi:SAME#2', 'same', 'SAME', 'finding', 'Goma de silicona: diámetro medio de 227 nm, pero casi la mitad de la masa en partículas mayores de 1000 nm.', 'fs_same');
INSERT INTO knowledge_chunks VALUES ('psi:SAME#3', 'same', 'SAME', 'finding', 'Al envejecer, baja mucho el número de partículas y la masa se mantiene: coagulación.', 'fs_same');
INSERT INTO knowledge_chunks VALUES ('psi:SAME#4', 'same', 'SAME', 'finding', 'Todas las muestras generaron muchas partículas submicrónicas, que un detector por ionización capta mejor; el de dispersión de luz funciono bien en la mayoría de los casos.', 'fs_same');
INSERT INTO investigations VALUES ('samer', 'SAME-R', 'Smoke Aerosol Measurement Experiment - Reflight', 'SAME', '{"deteccion"}', 5, 'aerosol', '{"Teflon", "Kapton", "algodón", "goma de silicona", "Pyrell"}', 21.0, 21.0, 'cabina', 101.3, 101.3, 'cabina', 0.0, 20.0, 'planificado', 0.0, 'ISS (Expedición 24)', 'MSG', 'Hardware SAME', '2010', 'si', 'Repetir SAME para analizar distribuciones de tamaño de partículas y comparar vuelo con ensayos en tierra; evaluar detectores de ISS y Shuttle.', 'Material y temperatura de la muestra; incluyó temperaturas de calentamiento más altas y ensayos sin flujo durante el calentamiento.', '{"precipitador térmico (muestras para TEM)", "instrumentos de aerosol", "detector de humo comercial", "SMPS en tierra", "M-pass (reemplazó a uno de los equipos comerciales de SAME)"}', '{"id": "samer", "acronym": "SAME-R", "name": "Smoke Aerosol Measurement Experiment - Reflight", "family": "SAME", "pillars": ["deteccion"], "directness": 5, "directness_reason": "Nombrada en el enunciado como estudio de detección.", "fuel_phase": "aerosol", "fuels": ["Teflon", "Kapton", "algodón", "goma de silicona", "Pyrell"], "geometry": "Muestras sobrecalentadas con temperatura superficial repetible.", "o2": {"min": 21.0, "max": 21.0, "basis": "cabina", "note": "Aire estándar ISS dentro de MSG."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "101.3 kPa en MSG."}, "flow": {"min": 0.0, "max": 20.0, "basis": "planificado", "note": "Caudal controlado e incluyó ensayos sin flujo en MSG."}, "gravity": 0.0, "platform": "ISS (Expedición 24)", "facility": "MSG", "hardware": "Hardware SAME", "years": "2010", "objectives": "Repetir SAME para analizar distribuciones de tamaño de partículas y comparar vuelo con ensayos en tierra; evaluar detectores de ISS y Shuttle.", "variables": "Material y temperatura de la muestra; incluyó temperaturas de calentamiento más altas y ensayos sin flujo durante el calentamiento.", "diagnostics": ["precipitador térmico (muestras para TEM)", "instrumentos de aerosol", "detector de humo comercial", "SMPS en tierra", "M-pass (reemplazó a uno de los equipos comerciales de SAME)"], "findings": [{"text": "El detector del Shuttle (ionización) descartaba partículas mayores de 1-2 um; el de la ISS (dispersión en infrarrojo cercano) es más sensible a partículas mayores de 1 um.", "source": "fs_same"}], "pi": "Yuan, Fortenberry, Urban, Yang, Cleary, Mulholland (según PSI)", "in_psi": "si", "sources": ["psi_101", "fs_same", "challenge"], "psi": {"id": "PSI-101", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-101", "project_start": "07-01-2010", "project_end": "09-30-2010", "platform": "International Space Station (ISS)", "hardware": "Comparitive Soot Diagnostic Hardware; Refer to final report", "keywords": ["Soot", "Flames", "Pyrell", "SAME", "Transmission Electron Microscopy", "Silicon Rubber", "Spacecraft Fire Safety", "Teflon", "Cotton", "Smoke", "Kapton", "SAME-2"], "reused_by": []}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:SAME-R#1', 'samer', 'SAME-R', 'finding', 'El detector del Shuttle (ionización) descartaba partículas mayores de 1-2 um; el de la ISS (dispersión en infrarrojo cercano) es más sensible a partículas mayores de 1 um.', 'fs_same');
INSERT INTO investigations VALUES ('daft', 'DAFT / DAFT-2', 'Dust and Aerosol Measurement Feasibility Test', 'SAME', '{"deteccion"}', 3, 'aerosol', '{"polvo ambiental de la ISS (sin combustión)"}', 21.0, 21.0, 'cabina', 101.3, 101.3, 'cabina', 5.0, 15.0, 'cabina', 0.0, 'ISS (Expediciones 10-13)', 'Cabina de la ISS', 'Contador de partículas ultrafinas P-Trak', '2005-2006', 'si', 'Caracterizar las partículas en el aire de la ISS para juzgar si los detectores de humo son adecuados, y probar el contador P-Trak antes de usarlo en SAME.', 'Ubicación y momento de la medición (maximo tres puntos por día).', '{"contador de partículas ultrafinas P-Trak"}', '{"id": "daft", "acronym": "DAFT / DAFT-2", "name": "Dust and Aerosol Measurement Feasibility Test", "family": "SAME", "pillars": ["deteccion"], "directness": 3, "directness_reason": "Mide polvo, no humo: define el ''ruido de fondo'' que debe distinguir un detector.", "fuel_phase": "aerosol", "fuels": ["polvo ambiental de la ISS (sin combustión)"], "geometry": "No aplica.", "o2": {"min": 21.0, "max": 21.0, "basis": "cabina", "note": "Aire de cabina habitable ISS."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "101.3 kPa en cabina ISS."}, "flow": {"min": 5.0, "max": 15.0, "basis": "cabina", "note": "Corrientes de ventilación ambiental de cabina ISS."}, "gravity": 0.0, "platform": "ISS (Expediciones 10-13)", "facility": "Cabina de la ISS", "hardware": "Contador de partículas ultrafinas P-Trak", "years": "2005-2006", "objectives": "Caracterizar las partículas en el aire de la ISS para juzgar si los detectores de humo son adecuados, y probar el contador P-Trak antes de usarlo en SAME.", "variables": "Ubicación y momento de la medición (maximo tres puntos por día).", "diagnostics": ["contador de partículas ultrafinas P-Trak"], "findings": [{"text": "Los niveles de partículas en la ISS fueron bajos comparados con el Shuttle.", "source": "fs_daft"}, {"text": "El tamaño medio de partícula en órbita fue mayor que en la Tierra.", "source": "fs_daft"}], "pi": "Urban, Fortenberry (según PSI)", "in_psi": "si", "sources": ["psi_47", "fs_daft", "challenge"], "psi": {"id": "PSI-47", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-47", "project_start": "03-01-2003", "project_end": "06-01-2009", "platform": "International Space Station (ISS)", "hardware": "TSI P-Trak", "keywords": ["DAFT", "Condensate Nuclei Counter", "Laser scattering aerosol device", "Fire safety", "Space hardware testing", "P-Trak particulate counter", "Capillary Fluid Motion", "Combustion", "Smoke", "Fire prevention"], "reused_by": []}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:DAFT / DAFT-2#1', 'daft', 'DAFT / DAFT-2', 'finding', 'Los niveles de partículas en la ISS fueron bajos comparados con el Shuttle.', 'fs_daft');
INSERT INTO knowledge_chunks VALUES ('psi:DAFT / DAFT-2#2', 'daft', 'DAFT / DAFT-2', 'finding', 'El tamaño medio de partícula en órbita fue mayor que en la Tierra.', 'fs_daft');
INSERT INTO investigations VALUES ('flex', 'FLEX', 'Flame Extinguishment Experiment', 'FLEX', '{"supresion", "prevencion"}', 5, 'liquido', '{"metanol", "heptano"}', 10.0, 50.0, 'planificado', 50.7, 304.0, 'medido', 0.0, 0.0, 'medido', 0.0, 'ISS', 'CIR', 'MDCA', '2009-2012', 'si', 'Cuantificar la eficacia de supresores gaseosos inertes en microgravedad, obtener un índice límite de oxígeno (LOI) conservador y mapear los límites de inflamabilidad de combustibles líquidos.', 'Combustible, tamaño de gota, fracción de O2, presión y diluyente/supresor (N2, CO2, He y, según PSI, SF6; hasta ~0,70 de fracción molar).', '{"tasa de quemado de gota", "extinción de llama", "radiación de llama", "concentración de hollín", "temperatura de hollín"}', '{"id": "flex", "acronym": "FLEX", "name": "Flame Extinguishment Experiment", "family": "FLEX", "pillars": ["supresion", "prevencion"], "directness": 5, "directness_reason": "Nombrada en el enunciado como el estudio de supresión.", "fuel_phase": "liquido", "fuels": ["metanol", "heptano"], "geometry": "Gotas aisladas de 1,5 a 5 mm de diámetro inicial.", "o2": {"min": 10.0, "max": 50.0, "basis": "planificado", "note": "Ejecutado en los primeros resultados: 10-40%."}, "pressure": {"min": 50.7, "max": 304.0, "basis": "medido", "note": "Plan: 0,5-1,0 atm. Primeros resultados: 0,7-3,0 atm. La ficha de PSI indica 0,5-1,5 atm para los ensayos de índice límite de oxígeno."}, "flow": {"min": 0.0, "max": 0.0, "basis": "medido", "note": "Ambiente quieto."}, "gravity": 0.0, "platform": "ISS", "facility": "CIR", "hardware": "MDCA", "years": "2009-2012", "objectives": "Cuantificar la eficacia de supresores gaseosos inertes en microgravedad, obtener un índice límite de oxígeno (LOI) conservador y mapear los límites de inflamabilidad de combustibles líquidos.", "variables": "Combustible, tamaño de gota, fracción de O2, presión y diluyente/supresor (N2, CO2, He y, según PSI, SF6; hasta ~0,70 de fracción molar).", "diagnostics": ["tasa de quemado de gota", "extinción de llama", "radiación de llama", "concentración de hollín", "temperatura de hollín"], "findings": [{"text": "LOI en mezclas O2/N2: 0,12 para metanol y 0,15 para heptano.", "source": "flex_first"}, {"text": "Descubrimiento de las llamas frías: tras apagarse la llama visible, las gotas grandes de heptano siguieron quemándose.", "source": "flex_first"}, {"text": "Al bajar el O2 ambiente, crece el diámetro de extinción difusiva y disminuye el de extinción radiativa.", "source": "flex_first"}], "pi": "Shaw, Hicks, Williams, Nayagam, Choi, Dryer, Dietrich (según PSI)", "in_psi": "si", "sources": ["psi_69", "fs_flex", "flex_first", "challenge"], "psi": {"id": "PSI-69", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-69", "project_start": "08-01-2007", "project_end": "07-31-2016", "platform": "International Space Station (ISS)", "hardware": "Combustion Integrated Rack (CIR)-Fluids and Combustion Facility (FCF); Multi-user Droplet Combustion Appartatus (MDCA)", "keywords": ["FLEX", "Droplet", "Diffusion Flames", "Fuel Sooting", "Spacecraft Fire Safety", "Flames"], "reused_by": ["PSI-117", "PSI-142"]}, "pressure_psi": {"min": 7.4, "max": 44.1, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:FLEX#1', 'flex', 'FLEX', 'finding', 'LOI en mezclas O2/N2: 0,12 para metanol y 0,15 para heptano.', 'flex_first');
INSERT INTO knowledge_chunks VALUES ('psi:FLEX#2', 'flex', 'FLEX', 'finding', 'Descubrimiento de las llamas frías: tras apagarse la llama visible, las gotas grandes de heptano siguieron quemándose.', 'flex_first');
INSERT INTO knowledge_chunks VALUES ('psi:FLEX#3', 'flex', 'FLEX', 'finding', 'Al bajar el O2 ambiente, crece el diámetro de extinción difusiva y disminuye el de extinción radiativa.', 'flex_first');
INSERT INTO investigations VALUES ('flex2', 'FLEX-2', 'Flame Extinguishment Experiment - 2', 'FLEX', '{"fundamental", "supresion"}', 3, 'liquido', '{"combustibles puros", "mezclas", "sustitutos bicomponente"}', 10.0, 40.0, 'medido', 50.7, 304.0, 'medido', 0.0, 5.0, 'medido', 0.0, 'ISS', 'CIR', 'MDCA', '2012-2015', 'si', 'Estudiar el efecto de flujos convectivos lentos en la tasa de quemado, la influencia de una segunda gota y combustibles prácticos; verificar modelos de combustión de gotas.', 'Tipo de combustible, composición del gas, presión, diámetro inicial de la gota, velocidad de traslación de la gota, y espaciado y tamaño en un arreglo lineal de dos gotas.', '{"video de la combustión"}', '{"id": "flex2", "acronym": "FLEX-2", "name": "Flame Extinguishment Experiment - 2", "family": "FLEX", "pillars": ["fundamental", "supresion"], "directness": 3, "directness_reason": "Combustibles prácticos y flujo convectivo; relación indirecta con seguridad.", "fuel_phase": "liquido", "fuels": ["combustibles puros", "mezclas", "sustitutos bicomponente"], "geometry": "Gotas de ~2-4 mm sobre fibras; pares de gotas en arreglo lineal.", "o2": {"min": 10.0, "max": 40.0, "basis": "medido", "note": "Fracción molar de O2 de 0,1 a 0,4. Fuente: ficha de PSI (PSI-68)."}, "pressure": {"min": 50.7, "max": 304.0, "basis": "medido", "note": "0,5 a 3,0 atm. Fuente: ficha de PSI (PSI-68)."}, "flow": {"min": 0.0, "max": 5.0, "basis": "medido", "note": "Flujo convectivo sub-boyante lento trasladando la gota (0-5 cm/s)."}, "gravity": 0.0, "platform": "ISS", "facility": "CIR", "hardware": "MDCA", "years": "2012-2015", "objectives": "Estudiar el efecto de flujos convectivos lentos en la tasa de quemado, la influencia de una segunda gota y combustibles prácticos; verificar modelos de combustión de gotas.", "variables": "Tipo de combustible, composición del gas, presión, diámetro inicial de la gota, velocidad de traslación de la gota, y espaciado y tamaño en un arreglo lineal de dos gotas.", "diagnostics": ["video de la combustión"], "findings": [], "pi": "Dryer, Shaw, Choi, Nayagam, Avedisian, Dietrich, Hicks, Williams (según PSI)", "in_psi": "si", "sources": ["psi_68", "fs_flex", "challenge"], "psi": {"id": "PSI-68", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-68", "project_start": "08-12-2016", "project_end": "09-30-2019", "platform": "International Space Station (ISS)", "hardware": "Combustion Integrated Rack (CIR); Multi-user Droplet Combustion Appartatus (MDCA)", "keywords": ["FLEX", "Decane", "Radiative Extinction", "Flame Extinction", "Microgravity Combustion", "Diffusive Extinction", "Multiple Droplet Combustion Apparatus", "Droplet Combustion", "Spacecraft Fire Safety", "Ethanol", "Soot Formation"], "reused_by": []}, "pressure_psi": {"min": 7.4, "max": 44.1, "basis": "medido"}}'::jsonb);
INSERT INTO investigations VALUES ('cfi', 'CFI', 'Cool Flames Investigation', 'FLEX', '{"fundamental", "supresion"}', 3, 'liquido', '{"n-dodecano", "mezclas de n-dodecano e iso-dodecano"}', 15.0, 30.0, 'planificado', 25.3, 506.6, 'planificado', 0.0, 0.0, 'medido', 0.0, 'ISS', 'CIR', 'MDCA', '2017', 'si', 'Estudiar la combustión a baja temperatura (llamas frías) de gotas de combustible líquido.', 'Combustible y atmósfera.', '{}', '{"id": "cfi", "acronym": "CFI", "name": "Cool Flames Investigation", "family": "FLEX", "pillars": ["fundamental", "supresion"], "directness": 3, "directness_reason": "Las llamas frías son un riesgo oculto: combustión que sigue tras la extinción visible.", "fuel_phase": "liquido", "fuels": ["n-dodecano", "mezclas de n-dodecano e iso-dodecano"], "geometry": "Gotas de ~4 mm.", "o2": {"min": 15.0, "max": 30.0, "basis": "planificado", "note": "Rango cámara CIR-MDCA."}, "pressure": {"min": 25.3, "max": 506.6, "basis": "planificado", "note": "Objetivo: 0,25 a 5 atm. El enfoque describe mezclas de gas entregadas a la cámara entre 0,25 y 0,5 atm. Fuente: ficha de PSI (PSI-39)."}, "flow": {"min": 0.0, "max": 0.0, "basis": "medido", "note": "Ambiente quieto."}, "gravity": 0.0, "platform": "ISS", "facility": "CIR", "hardware": "MDCA", "years": "2017", "objectives": "Estudiar la combustión a baja temperatura (llamas frías) de gotas de combustible líquido.", "variables": "Combustible y atmósfera.", "diagnostics": [], "findings": [{"text": "La llama caliente oscila y se apaga; la gota sigue consumiéndose con una llama fría casi invisible, dejando una nube de vapor sin quemar.", "source": "cfi_blog"}], "pi": "Dryer, Dietrich, Farouk, Nayagam, Williams (según PSI)", "in_psi": "si", "sources": ["psi_39", "cfi_blog", "challenge"], "psi": {"id": "PSI-39", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-39", "project_start": "10-01-2020", "project_end": "10-20-2021", "platform": "International Space Station (ISS)", "hardware": "Multi-User Droplet Combustion Apparatus (MDCA); Combustion Integrated Rack (CIR)", "keywords": ["Droplet combustion", "Extinction", "Helium dilution", "n-dodecane cool flames", "Flame dynamics", "Alkane chemistry", "Negative Temperature Coefficient (NTC)", "Low-temperature chemistry", "hydrocarbon fuel combustion", "Renewable jet fuel"], "reused_by": []}, "pressure_psi": {"min": 3.7, "max": 73.5, "basis": "planificado"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:CFI#1', 'cfi', 'CFI', 'finding', 'La llama caliente oscila y se apaga; la gota sigue consumiéndose con una llama fría casi invisible, dejando una nube de vapor sin quemar.', 'cfi_blog');
INSERT INTO investigations VALUES ('bre', 'ACME-BRE', 'Burning Rate Emulator', 'ACME', '{"prevencion"}', 4, 'gas', '{"etileno", "metano", "diluidos con nitrógeno (emulan papel, plástico, alcohol)"}', 21.0, 40.0, 'medido', 57.0, 100.0, 'medido', 0.0, 0.0, 'medido', 0.0, 'ISS', 'CIR', 'Inserto de cámara ACME', '2019-2021', 'si', 'Entender la ignición y extinción de materiales y evaluar métodos de ensayo de inflamabilidad para baja gravedad y gravedad parcial.', 'Caudal de combustible, dilución, fracción de O2, presión y diámetro del quemador.', '{"sensores de flujo de calor", "termopar de superficie", "radiómetros", "video color"}', '{"id": "bre", "acronym": "ACME-BRE", "name": "Burning Rate Emulator", "family": "ACME", "pillars": ["prevencion"], "directness": 4, "directness_reason": "Emula con gas la inflamabilidad de sólidos y líquidos en atmósfera quieta; cubre O2 enriquecido y baja presión.", "fuel_phase": "gas", "fuels": ["etileno", "metano", "diluidos con nitrógeno (emulan papel, plástico, alcohol)"], "geometry": "Quemador poroso plano de 25 y 50 mm de diámetro, con dos sensores de flujo de calor y termopar de superficie.", "o2": {"min": 21.0, "max": 40.0, "basis": "medido", "note": "Atmósferas consideradas para misiones tripuladas según la ficha de PSI (PSI-20): 14,7 psia con 21 % de O2; 10,2 psia con 26,5 %; y 8,2 psia con 34 %."}, "pressure": {"min": 57.0, "max": 100.0, "basis": "medido"}, "flow": {"min": 0.0, "max": 0.0, "basis": "medido", "note": "Atmósfera quieta."}, "gravity": 0.0, "platform": "ISS", "facility": "CIR", "hardware": "Inserto de cámara ACME", "years": "2019-2021", "objectives": "Entender la ignición y extinción de materiales y evaluar métodos de ensayo de inflamabilidad para baja gravedad y gravedad parcial.", "variables": "Caudal de combustible, dilución, fracción de O2, presión y diámetro del quemador.", "diagnostics": ["sensores de flujo de calor", "termopar de superficie", "radiómetros", "video color"], "findings": [{"text": "Todas las llamas en 21% de O2 se autoextinguieron en menos de 40 s; con 26,5%, 34% y 40% de O2 se observaron llamas estables.", "source": "bre_dehghani"}, {"text": "El tiempo hasta la extinción escala con el cubo de la fracción de O2 y no depende de la presión: evidencia del riesgo de atmósferas enriquecidas en oxígeno.", "source": "bre_wright"}], "pi": "de Ris, Sunderland, Quintiere, Stocker (según PSI)", "in_psi": "si", "sources": ["psi_20", "fs_acme", "bre_wright", "bre_dehghani", "challenge"], "psi": {"id": "PSI-20", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-20", "project_start": "01-01-2010", "project_end": "02-08-2025", "platform": "International Space Station (ISS)", "hardware": "Combustion Integrated Rack (CIR); ACME", "keywords": ["Buoyancy", "Diffusion Flames", "Fire Safety", "Heat Flux", "Radiative Extinction", "Polymer", "ACME", "Extinction Limit", "Flammability", "Modeling", "Triple Flame"], "reused_by": []}, "pressure_psi": {"min": 8.3, "max": 14.5, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:ACME-BRE#1', 'bre', 'ACME-BRE', 'finding', 'Todas las llamas en 21% de O2 se autoextinguieron en menos de 40 s; con 26,5%, 34% y 40% de O2 se observaron llamas estables.', 'bre_dehghani');
INSERT INTO knowledge_chunks VALUES ('psi:ACME-BRE#2', 'bre', 'ACME-BRE', 'finding', 'El tiempo hasta la extinción escala con el cubo de la fracción de O2 y no depende de la presión: evidencia del riesgo de atmósferas enriquecidas en oxígeno.', 'bre_wright');
INSERT INTO investigations VALUES ('cfig', 'ACME-CFI-G', 'Cool Flames Investigation with Gases', 'ACME', '{"fundamental"}', 3, 'gas', '{"propano", "n-butano", "n-pentano (objetivo según la ficha de PSI)", "etano (según ISS National Lab)"}', 21.0, 85.0, 'medido', 101.3, 101.3, 'cabina', 2.0, 15.0, 'planificado', 0.0, 'ISS', 'CIR', 'Inserto de cámara ACME', '2021', 'si', 'Observar llamas frías de difusión esféricas, estables o cuasi estables, y mejorar los modelos cinéticos de llama fría.', 'Combustible gaseoso y composición del oxidante.', '{}', '{"id": "cfig", "acronym": "ACME-CFI-G", "name": "Cool Flames Investigation with Gases", "family": "ACME", "pillars": ["fundamental"], "directness": 3, "directness_reason": "Tiene las concentraciones de O2 más altas en microgravedad de todo PSI.", "fuel_phase": "gas", "fuels": ["propano", "n-butano", "n-pentano (objetivo según la ficha de PSI)", "etano (según ISS National Lab)"], "geometry": "Quemador esférico poroso; llama ''invertida'': el oxidante sale del quemador hacia una cámara con N2 y gas inflamable.", "o2": {"min": 21.0, "max": 85.0, "basis": "medido", "note": "Hasta 85% de O2 en mezcla O2/N2 desde quemador esférico."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "101.3 kPa nominal en cámara CIR."}, "flow": {"min": 2.0, "max": 15.0, "basis": "planificado", "note": "Flujo desde quemador esférico poroso."}, "gravity": 0.0, "platform": "ISS", "facility": "CIR", "hardware": "Inserto de cámara ACME", "years": "2021", "objectives": "Observar llamas frías de difusión esféricas, estables o cuasi estables, y mejorar los modelos cinéticos de llama fría.", "variables": "Combustible gaseoso y composición del oxidante.", "diagnostics": [], "findings": [], "pi": "Stocker, Sunderland, Axelbaum, Williams (según PSI)", "in_psi": "si", "sources": ["psi_159", "fs_acme", "cfig_issnl", "challenge"], "psi": {"id": "PSI-159", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-159", "project_start": null, "project_end": null, "platform": "International Space Station (ISS)", "hardware": "ACME; Combustion Integrated Rack (CIR)", "keywords": ["chemical kinetics", "ethane", "heat loss", "low-temperature combustion", "porous burner", "dilution", "formaldehyde", "intensified video camera", "n-butane", "negative-temperature coefficient"], "reused_by": []}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO investigations VALUES ('cld', 'ACME-CLD Flame', 'Coflow Laminar Diffusion Flame', 'ACME', '{"fundamental"}', 2, 'gas', '{"metano", "etileno", "diluidos con nitrógeno"}', 21.0, 21.0, 'planificado', 101.3, 101.3, 'cabina', 5.0, 30.0, 'planificado', 0.0, 'ISS', 'CIR', 'Inserto de cámara ACME', '2017-2019', 'si', 'Extender el modelado predictivo a llamas con mucho hollín y a llamas muy diluidas cerca de la extinción.', 'Velocidad de inyección y dilución del combustible.', '{"fracción volumétrica de hollín", "pirometría", "imagenes CH*"}', '{"id": "cld", "acronym": "ACME-CLD Flame", "name": "Coflow Laminar Diffusion Flame", "family": "ACME", "pillars": ["fundamental"], "directness": 2, "directness_reason": "Validación de modelos de hollín y extinción; relación indirecta con seguridad.", "fuel_phase": "gas", "fuels": ["metano", "etileno", "diluidos con nitrógeno"], "geometry": "Quemador de co-flujo; llamas despegadas del quemador.", "o2": {"min": 21.0, "max": 21.0, "basis": "planificado", "note": "Co-flujo de aire."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "101.3 kPa en cámara CIR."}, "flow": {"min": 5.0, "max": 30.0, "basis": "planificado", "note": "Co-flujo laminar de aire."}, "gravity": 0.0, "platform": "ISS", "facility": "CIR", "hardware": "Inserto de cámara ACME", "years": "2017-2019", "objectives": "Extender el modelado predictivo a llamas con mucho hollín y a llamas muy diluidas cerca de la extinción.", "variables": "Velocidad de inyección y dilución del combustible.", "diagnostics": ["fracción volumétrica de hollín", "pirometría", "imagenes CH*"], "findings": [{"text": "Las llamas con hollín en microgravedad son más altas, anchas y frías que en 1 g; la fracción de hollín es de cinco a ocho veces mayor.", "source": "fs_acme"}, {"text": "Las llamas muy diluidas son más estables en microgravedad.", "source": "fs_acme"}], "pi": "Smooke, Stocker, Long (según PSI)", "in_psi": "si", "sources": ["psi_21", "fs_acme", "challenge"], "psi": {"id": "PSI-21", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-21", "project_start": "10-01-2006", "project_end": "05-31-2022", "platform": "International Space Station (ISS)", "hardware": "Combustion Integrated Rack (CIR); ACME", "keywords": ["microgravity", "ACME CLD Flame", "Fuels", "laminar diffusion flames", "Combustion Integrated Rack", "Flames"], "reused_by": []}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
