tart": "11-18-2016", "project_end": "11-17-2020", "platform": "International Space Station (ISS)", "hardware": "Combustion Integrated Rack (CIR); ACME", "keywords": ["Methane flames", "Coflow burner", "OH PLIF", "Carbon monoxide", "Ion-driven Convection", "Diffusion Flames", "Electric field flames", "CO PLIF", "Impinging flame", "Chemi-ionization"], "reused_by": []}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}, "emulated_gravity_g": {"min": 0.0, "max": 0.25, "representative": 0.167, "note": "Convección por viento iónico que mimetiza gravedad parcial lunar."}}'::jsonb);
INSERT INTO investigations VALUES ('flamedesign', 'ACME-Flame Design', 'Flame Design', 'ACME', '{"fundamental"}', 2, 'gas', '{"etileno", "metano"}', 21.0, 40.0, 'planificado', 101.3, 101.3, 'cabina', 1.0, 10.0, 'planificado', 0.0, 'ISS', 'CIR', 'Inserto de cámara ACME', '2019-2020', 'si', 'Entender el inicio del hollín y los límites de extinción para diseñar llamas robustas y sin hollín.', 'Concentraciones de combustible y oxígeno, y dirección del flujo.', '{}', '{"id": "flamedesign", "acronym": "ACME-Flame Design", "name": "Flame Design", "family": "ACME", "pillars": ["fundamental"], "directness": 2, "directness_reason": "Limites de hollín y extinción en atmósferas enriquecidas en O2.", "fuel_phase": "gas", "fuels": ["etileno", "metano"], "geometry": "Quemador esférico; llamas normales e invertidas.", "o2": {"min": 21.0, "max": 40.0, "basis": "planificado", "note": "Atmósfera enriquecida en O2 en CIR."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "101.3 kPa en cámara CIR."}, "flow": {"min": 1.0, "max": 10.0, "basis": "planificado", "note": "Flujo radial en quemador esférico."}, "gravity": 0.0, "platform": "ISS", "facility": "CIR", "hardware": "Inserto de cámara ACME", "years": "2019-2020", "objectives": "Entender el inicio del hollín y los límites de extinción para diseñar llamas robustas y sin hollín.", "variables": "Concentraciones de combustible y oxígeno, y dirección del flujo.", "diagnostics": [], "findings": [], "pi": "Axelbaum, Sunderland, Urban, Frolov, Stocker (según PSI)", "in_psi": "si", "sources": ["psi_10", "fs_acme", "challenge"], "psi": {"id": "PSI-10", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-10", "project_start": "01-14-1999", "project_end": "04-30-2025", "platform": "International Space Station (ISS)", "hardware": "Advanced Combustion via Microgravity Experiments (ACME); Combustion Integrated Rack (CIR); Reconfiguration of Combustion Integrated Rack (CIR)", "keywords": ["chemical kinetics", "ethylen