INSERT INTO investigations VALUES ('sflame', 'ACME-s-Flame', 'Structure and Response of Spherical Diffusion Flames', 'ACME', '{"fundamental"}', 2, 'gas', '{"hidrógeno", "metano", "etileno", "con diluyentes inertes"}', 15.0, 30.0, 'planificado', 101.3, 101.3, 'cabina', 1.0, 10.0, 'planificado', 0.0, 'ISS', 'CIR', 'Inserto de cámara ACME', '2017-2018', 'si', 'Predecir la estructura, la dinámica y la extinción de llamas con y sin hollín, e identificar inestabilidades pulsantes.', 'Combustible, diluyente y caudal.', '{"seis termopares de campo lejano", "radiómetro de vista amplia", "pirometría de filamento delgado"}', '{"id": "sflame", "acronym": "ACME-s-Flame", "name": "Structure and Response of Spherical Diffusion Flames", "family": "ACME", "pillars": ["fundamental"], "directness": 2, "directness_reason": "Limites de extinción radiativa y convectiva de llamas esféricas.", "fuel_phase": "gas", "fuels": ["hidrógeno", "metano", "etileno", "con diluyentes inertes"], "geometry": "Quemador esférico poroso.", "o2": {"min": 15.0, "max": 30.0, "basis": "planificado", "note": "Cámara CIR con diluyentes inertes."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "101.3 kPa en cámara CIR."}, "flow": {"min": 1.0, "max": 10.0, "basis": "planificado", "note": "Quemador esférico poroso."}, "gravity": 0.0, "platform": "ISS", "facility": "CIR", "hardware": "Inserto de cámara ACME", "years": "2017-2018", "objectives": "Predecir la estructura, la dinámica y la extinción de llamas con y sin hollín, e identificar inestabilidades pulsantes.", "variables": "Combustible, diluyente y caudal.", "diagnostics": ["seis termopares de campo lejano", "radiómetro de vista amplia", "pirometría de filamento delgado"], "findings": [], "pi": "Stocker, Law, Tse (según PSI)", "in_psi": "si", "sources": ["psi_23", "fs_acme", "challenge"], "psi": {"id": "PSI-23", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-23", "project_start": "02-05-2015", "project_end": "11-24-2019"