INSERT INTO investigations VALUES ('spice', 'SPICE', 'Smoke Point In Co-flow Experiment', 'MSG gas', '{"fundamental", "deteccion"}', 2, 'gas', '{"propileno", "propano", "etileno", "mezclas"}', 21.0, 21.0, 'cabina', 101.3, 101.3, 'cabina', 5.4, 65.0, 'medido', 0.0, 'ISS', 'MSG', 'Ducto de flujo SPICE', '2009', 'si', 'Determinar el punto de humo laminar (la mayor llama de difusión que no emite hollín) para varios combustibles, boquillas y co-flujos.', 'Combustible, diámetro de boquilla y velocidad de co-flujo.', '{"forma luminosa de la llama", "altura de estabilización", "campo de temperatura"}', '{"id": "spice", "acronym": "SPICE", "name": "Smoke Point In Co-flow Experiment", "family": "MSG gas", "pillars": ["fundamental", "deteccion"], "directness": 2, "directness_reason": "Inicio del hollín (humo) en microgravedad; su ducto de flujo fue reutilizado por BASS.", "fuel_phase": "gas", "fuels": ["propileno", "propano", "etileno", "mezclas"], "geometry": "Llamas de chorro con quemadores de 0,41 mm, 0,76 mm y 1,6 mm de diámetro, en co-flujo de aire.", "o2": {"min": 21.0, "max": 21.0, "basis": "cabina", "note": "Aire de cabina ISS en MSG."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "101.3 kPa en MSG."}, "flow": {"min": 5.4, "max": 65.0, "basis": "medido", "note": "Velocidad del co-flujo de aire. Fuente: ficha de PSI (PSI-107)."}, "gravity": 0.0, "platform": "ISS", "facility": "MSG", "hardware": "Ducto de flujo SPICE", "years": "2009", "objectives": "Determinar el punto de humo laminar (la mayor llama de difusión que no emite hollín) para varios combustibles, boquillas y co-flujos.", "variables": "Combustible, diámetro de boquilla y velocidad de co-flujo.", "diagnostics": ["forma luminosa de la llama", "altura de estabilización", "campo de temperatura"], "findings": [{"text": "Se completaron 250 ensayos de combustión y se identificaron más de 70 puntos de humo.", "source": "fs_spice"}], "pi": "Sunderland, Urban (según PSI)", "in_psi": "si", "sources": ["psi_107", "fs_spice", "challenge"], "psi": {"id": "PSI-107", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-107", "project_start": null, "project_end": null, "platform": "International Space Station (ISS)", "hardware": "Microgravity Science Glovebox (MSG)", "keywords": ["Soot", "Emisssions", "Laminar diffusion flames", "butane-lighter flame"], "reused_by": ["PSI-60"]}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:SPICE#1', 'spice', 'SPICE', 'finding', 'Se completaron 250 ensayos de combustión y se identificaron más de 70 puntos de humo.', 'fs_spice');
INSERT INTO investigations VALUES ('slice', 'SLICE', 'Structure & Liftoff In Combustion Experiment', 'MSG gas', '{"fundamental"}', 2, 'gas', '{"metano", "etileno", "diluidos con nitrógeno"}', 21.0, 21.0, 'cabina', 101.3, 101.3, 'cabina', 5.0, 40.0, 'medido', 0.0, 'ISS', 'MSG', 'Ducto de flujo SPICE', '2012', 'si', 'Caracterizar la estructura de la base de la llama, de adherida a despegada, e identificar los límites de velocidad de despegue.', 'Combustible, dilución, diámetro de quemador y velocidad de co-flujo.', '{"fotografía", "video"}', '{"id": "slice", "acronym": "SLICE", "name": "Structure & Liftoff In Combustion Experiment", "family": "MSG gas", "pillars": ["fundamental"], "directness": 2, "directness_reason": "Estabilidad y desprendimiento de llamas; precursor de CLD Flame.", "fuel_phase": "gas", "fuels": ["metano", "etileno", "diluidos con nitrógeno"], "geometry": "Llamas de chorro en co-flujo de aire con las boquillas de SPICE.", "o2": {"min": 21.0, "max": 21.0, "basis": "cabina", "note": "Aire de cabina ISS en MSG."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "101.3 kPa en MSG."}, "flow": {"min": 5.0, "max": 40.0, "basis": "medido", "note": "Co-flujo incrementado por pasos hasta el despegue (liftoff) de la llama."}, "gravity": 0.0, "platform": "ISS", "facility": "MSG", "hardware": "Ducto de flujo SPICE", "years": "2012", "objectives": "Caracterizar la estructura de la base de la llama, de adherida a despegada, e identificar los límites de velocidad de despegue.", "variables": "Combustible, dilución, diámetro de quemador y velocidad de co-flujo.", "diagnostics": ["fotografía", "video"], "findings": [{"text": "El punto de anclaje de la llama controla la estabilidad de la llama de difusión que le sigue.", "source": "fs_slice"}], "pi": "Smooke, Takahashi, Long, Stocker (según PSI)", "in_psi": "si", "sources": ["psi_106", "fs_slice", "fs_acme", "challenge"], "psi": {"id": "PSI-106", "url": "https://psi.nasa.gov/physci/repo/data/investigations/PSI-106", "project_start": null, "project_end": null, "platform": "International Space Station (ISS)", "hardware": null, "keywords": ["fuel dilution", "Diffusion Flame", "inlet velocity", "Fuels"], "reused_by": []}, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:SLICE#1', 'slice', 'SLICE', 'finding', 'El punto de anclaje de la llama controla la estabilidad de la llama de difusión que le sigue.', 'fs_slice');
INSERT INTO investigations VALUES ('sofie', 'SoFIE', 'Solid Fuel Ignition and Extinction', 'SoFIE', '{"prevencion", "supresion"}', 5, 'solido', '{"PMMA (láminas de acrílico de 0,05 a 1 mm)", "combustibles sólidos delgados y gruesos"}', 30.0, 30.0, 'medido', 50.7, 101.3, 'medido', 0.0, 0.0, 'medido', 0.0, 'ISS', 'CIR', 'Inserto SoFIE', '2022-2025', 'no', 'Estudiar ignición, propagación y extinción sobre sólidos y correlacionar los ensayos de inflamabilidad en 1 g con datos de microgravedad ventilada.', 'O2, presión, velocidad de flujo, espesor y geometría.', '{"medición de calentamiento de la muestra"}', '{"id": "sofie", "acronym": "SoFIE", "name": "Solid Fuel Ignition and Extinction", "family": "SoFIE", "pillars": ["prevencion", "supresion"], "directness": 5, "directness_reason": "Inflamabilidad de sólidos en O2 alto siguiendo la curva normoxica; investigación en curso.", "fuel_phase": "solido", "fuels": ["PMMA (láminas de acrílico de 0,05 a 1 mm)", "combustibles sólidos delgados y gruesos"], "geometry": "Cinco sub-investigaciones: NCA (láminas planas de PMMA), GEL (esfera de 4-5 cm), MIST (cilindros), RTDFS (combustibles delgados), SMuRF.", "o2": {"min": 30.0, "max": 30.0, "basis": "medido", "note": "Ensayos RTDFS sobre láminas de acrílico (Carmignani et al. 2026, pág. 1). La sub-investigación NCA planificaba de 21 % a 85 % (página de NASA Glenn)."}, "pressure": {"min": 50.7, "max": 101.3, "basis": "medido", "note": "0,5 y 1 atm en los ensayos RTDFS (Carmignani et al. 2026, pág. 1)."}, "flow": {"min": 0.0, "max": 0.0, "basis": "medido", "note": "Ambiente quieto, sin flujo externo, en los ensayos RTDFS (Carmignani et al. 2026, pág. 1)."}, "gravity": 0.0, "platform": "ISS", "facility": "CIR", "hardware": "Inserto SoFIE", "years": "2022-2025", "objectives": "Estudiar ignición, propagación y extinción sobre sólidos y correlacionar los ensayos de inflamabilidad en 1 g con datos de microgravedad ventilada.", "variables": "O2, presión, velocidad de flujo, espesor y geometría.", "diagnostics": ["medición de calentamiento de la muestra"], "findings": [{"text": "En ambiente quieto con 30 % de O2, la llama avanzó más rápido sobre láminas de acrílico más delgadas, y con espesores mayores a 0,1 mm se apagó antes de llegar al final de la muestra.", "source": "p_carmignani2026", "page": 1}, {"text": "Cerca de la extinción aparecieron llamas oscilantes y pulsantes, con re-igniciones, que a veces persistieron varios minutos antes de apagarse: un riesgo porque las llamas pueden durar mucho incluso sin ventilación.", "source": "p_carmignani2026", "page": 7}, {"text": "La temperatura máxima del gas fue similar a 0,5 y a 1 atm (entre 1050 y 1200 °C), pero el flujo de calor radiativo a 0,5 atm fue aproximadamente la mitad que a 1 atm.", "source": "p_carmignani2026", "page": 1}, {"text": "Los ensayos confirmaron la predicción teórica de extinción por pérdidas radiativas: con 30 % de O2 se esperaba extinción para espesores de unos 0,1 mm a 1 atm y unos 0,06 mm a 0,5 atm, y solo los combustibles más delgados ardieron hasta el final.", "source": "p_carmignani2026", "page": 7}], "pi": "T''ien (GEL), Fernandez-Pello (MIST), Miller (NCA), Bhattacharjee (RTDFS), Olson (SMuRF)", "in_psi": "no", "sources": ["sofie", "nasa_combustion", "p_carmignani2026"], "psi": null, "pressure_psi": {"min": 7.4, "max": 14.7, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:SoFIE#1', 'sofie', 'SoFIE', 'finding', 'En ambiente quieto con 30 % de O2, la llama avanzó más rápido sobre láminas de acrílico más delgadas, y con espesores mayores a 0,1 mm se apagó antes de llegar al final de la muestra.', 'p_carmignani2026');
INSERT INTO knowledge_chunks VALUES ('psi:SoFIE#2', 'sofie', 'SoFIE', 'finding', 'Cerca de la extinción aparecieron llamas oscilantes y pulsantes, con re-igniciones, que a veces persistieron varios minutos antes de apagarse: un riesgo porque las llamas pueden durar mucho incluso sin ventilación.', 'p_carmignani2026');
INSERT INTO knowledge_chunks VALUES ('psi:SoFIE#3', 'sofie', 'SoFIE', 'finding', 'La temperatura máxima del gas fue similar a 0,5 y a 1 atm (entre 1050 y 1200 °C), pero el flujo de calor radiativo a 0,5 atm fue aproximadamente la mitad que a 1 atm.', 'p_carmignani2026');
INSERT INTO knowledge_chunks VALUES ('psi:SoFIE#4', 'sofie', 'SoFIE', 'finding', 'Los ensayos confirmaron la predicción teórica de extinción por pérdidas radiativas: con 30 % de O2 se esperaba extinción para espesores de unos 0,1 mm a 1 atm y unos 0,06 mm a 0,5 atm, y solo los combustibles más delgados ardieron hasta el final.', 'p_carmignani2026');
INSERT INTO investigations VALUES ('flare', 'FLARE', 'Flammability Limits At Reduced-g Experiment', 'Internacional', '{"prevencion"}', 4, 'solido', '{"materiales sólidos"}', 15.0, 35.0, 'planificado', 101.3, 101.3, 'cabina', 0.0, 25.0, 'planificado', 0.0, 'ISS (módulo Kibo, JAXA)', 'Kibo', 'Solid Combustion (JAXA)', '2020-2023', 'no', 'Desarrollar un método para correlacionar los límites de inflamabilidad en gravedad normal y en microgravedad, y proponer un nuevo ensayo de selección de materiales.', NULL, '{}', '{"id": "flare", "acronym": "FLARE", "name": "Flammability Limits At Reduced-g Experiment", "family": "Internacional", "pillars": ["prevencion"], "directness": 4, "directness_reason": "Busca estimar límites de inflamabilidad en microgravedad a partir de datos de tierra.", "fuel_phase": "solido", "fuels": ["materiales sólidos"], "geometry": null, "o2": {"min": 15.0, "max": 35.0, "basis": "planificado", "note": "Ensayos en módulo Kibo (JAXA)."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "101.3 kPa nominal en Kibo."}, "flow": {"min": 0.0, "max": 25.0, "basis": "planificado", "note": "Flujo forzado variable."}, "gravity": 0.0, "platform": "ISS (módulo Kibo, JAXA)", "facility": "Kibo", "hardware": "Solid Combustion (JAXA)", "years": "2020-2023", "objectives": "Desarrollar un método para correlacionar los límites de inflamabilidad en gravedad normal y en microgravedad, y proponer un nuevo ensayo de selección de materiales.", "variables": null, "diagnostics": [], "findings": [], "pi": "Osamu Fujita (PI JAXA); Sandra Olson, Carlos Fernandez-Pello (Co-I EE.UU.)", "in_psi": "no", "sources": ["flare", "nasa_combustion"], "psi": null, "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO investigations VALUES ('fm2', 'FM2', 'Flammability of Materials on the Moon', 'Gravedad parcial', '{"prevencion"}', 5, 'solido', '{"SIBAL (algodón-fibra de vidrio)", "otras tres muestras"}', 30.0, 34.0, 'planificado', 56.5, 70.3, 'planificado', 0.0, 15.0, 'planificado', 0.167, 'Superficie lunar', 'Cámara autónoma', 'FM2', 'futuro', 'no_aun', 'Hacer las primeras observaciones de propagación de llama en la Luna y comprobar si los materiales arden más fácilmente en gravedad parcial que en 1 g.', 'Material.', '{"cámaras", "temperatura de llama y combustible", "concentración de O2", "concentración de CO2"}', '{"id": "fm2", "acronym": "FM2", "name": "Flammability of Materials on the Moon", "family": "Gravedad parcial", "pillars": ["prevencion"], "directness": 5, "directness_reason": "Primer experimento de combustión en otro cuerpo planetario; llenaría la brecha de gravedad parcial.", "fuel_phase": "solido", "fuels": ["SIBAL (algodón-fibra de vidrio)", "otras tres muestras"], "geometry": "Cuatro muestras quemadas una a una en cámara sellada autónoma (28,5 x 28,5 x 38,5 cm, 25 kg).", "o2": {"min": 30.0, "max": 34.0, "basis": "planificado", "note": "Atmósfera lunar prevista (30% O2 o más)."}, "pressure": {"min": 56.5, "max": 70.3, "basis": "planificado", "note": "Presión lunar prevista (10.2 psi / 70.3 kPa o menos)."}, "flow": {"min": 0.0, "max": 15.0, "basis": "planificado", "note": "Cámara sellada autónoma lunar."}, "gravity": 0.167, "platform": "Superficie lunar", "facility": "Cámara autónoma", "hardware": "FM2", "years": "futuro", "objectives": "Hacer las primeras observaciones de propagación de llama en la Luna y comprobar si los materiales arden más fácilmente en gravedad parcial que en 1 g.", "variables": "Material.", "diagnostics": ["cámaras", "temperatura de llama y combustible", "concentración de O2", "concentración de CO2"], "findings": [], "pi": "Paul Ferkul (PI)", "in_psi": "no_aun", "sources": ["fm2", "challenge"], "psi": null, "pressure_psi": {"min": 8.2, "max": 10.2, "basis": "planificado"}}'::jsonb);
INSERT INTO investigations VALUES ('luci', 'LUCI', 'Lunar-g Combustion Investigation', 'Gravedad parcial', '{"prevencion"}', 5, 'solido', '{}', 21.0, 34.0, 'planificado', 56.5, 101.3, 'planificado', 0.0, 20.0, 'planificado', 0.167, NULL, NULL, NULL, 'futuro', 'no_aun', 'Investigación de combustión en gravedad lunar. El enunciado solo indica que sus datos se agregarán a PSI en el futuro.', NULL, '{}', '{"id": "luci", "acronym": "LUCI", "name": "Lunar-g Combustion Investigation", "family": "Gravedad parcial", "pillars": ["prevencion"], "directness": 5, "directness_reason": "Datos de combustión en gravedad lunar esperados en PSI.", "fuel_phase": "solido", "fuels": [], "geometry": null, "o2": {"min": 21.0, "max": 34.0, "basis": "planificado", "note": "Rango previsto para investigaciones en gravedad lunar."}, "pressure": {"min": 56.5, "max": 101.3, "basis": "planificado", "note": "Rango de presión de hábitat lunar."}, "flow": {"min": 0.0, "max": 20.0, "basis": "planificado", "note": "Rango de ventilación en superficie lunar."}, "gravity": 0.167, "platform": null, "facility": null, "hardware": null, "years": "futuro", "objectives": "Investigación de combustión en gravedad lunar. El enunciado solo indica que sus datos se agregarán a PSI en el futuro.", "variables": null, "diagnostics": [], "findings": [], "pi": null, "in_psi": "no_aun", "sources": ["challenge"], "psi": null, "pressure_psi": {"min": 8.2, "max": 14.7, "basis": "planificado"}}'::jsonb);
INSERT INTO investigations VALUES ('confined', 'Confined Combustion', 'Confined Combustion (combustión confinada en microgravedad)', 'BASS', '{"prevencion"}', 4, 'solido', '{"SIBAL (algodón-fibra de vidrio)", "PMMA (láminas de 1 mm; muestras de 100 x 22 x 1 mm)"}', 17.0, 21.0, 'medido', 101.3, 101.3, 'cabina', 2.6, 25.0, 'medido', 0.0, 'ISS', 'MSG', 'Ducto de flujo de BASS con deflectores ajustables', '2019-2024', 'no', 'Estudiar cómo el confinamiento (paredes cercanas) cambia la propagación de llama sobre sólidos en microgravedad, en flujo concurrente y opuesto.', 'Distancia entre deflectores, material del deflector (condición radiativa), velocidad del flujo, material y número de caras que arden.', '{}', '{"gravity": 0.0, "psi": null, "in_psi": "no", "years": "2019-2024", "pi": null, "variables": "Distancia entre deflectores, material del deflector (condición radiativa), velocidad del flujo, material y número de caras que arden.", "diagnostics": [], "id": "confined", "acronym": "Confined Combustion", "name": "Confined Combustion (combustión confinada en microgravedad)", "family": "BASS", "pillars": ["prevencion"], "directness": 4, "directness_reason": "Mide cómo las paredes cercanas cambian la propagación de llama, como en racks y compartimentos de una nave.", "fuel_phase": "solido", "fuels": ["SIBAL (algodón-fibra de vidrio)", "PMMA (láminas de 1 mm; muestras de 100 x 22 x 1 mm)"], "geometry": "Muestras entre dos placas paralelas (deflectores) a distancias de 1 a 5 cm, de policarbonato transparente, aluminio negro anodizado o aluminio pulido.", "o2": {"min": 17.0, "max": 21.0, "basis": "medido", "note": "Aire de cabina ISS y mezclas O2/N2 en ducto MSG (Li et al. 2020; Sharma et al. 2024)."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "1 atm nominal en MSG (ISS)."}, "flow": {"min": 2.6, "max": 25.0, "basis": "medido", "note": "Flujo concurrente de 5 a 25 cm/s (Li et al. 2020, pág. 9) y opuesto de 2,6 a 10,5 cm/s (Sharma et al. 2024, pág. 1)."}, "platform": "ISS", "facility": "MSG", "hardware": "Ducto de flujo de BASS con deflectores ajustables", "objectives": "Estudiar cómo el confinamiento (paredes cercanas) cambia la propagación de llama sobre sólidos en microgravedad, en flujo concurrente y opuesto.", "findings": [{"text": "En flujo concurrente sobre SIBAL existe una distancia mínima entre deflectores (cerca de 1 cm) bajo la cual la llama no avanza, por falta de oxígeno y pérdida de calor hacia las paredes.", "source": "p_li2020", "page": 9}, {"text": "El confinamiento tiene un efecto no monótono en flujo concurrente: la llama más larga y rápida se dio con una distancia de 4,0 cm entre deflectores; con más confinamiento la llama se debilita.", "source": "p_li2020", "page": 9}, {"text": "Los deflectores de aluminio pulido dieron las llamas más fuertes y los de policarbonato transparente las más débiles, porque la radiación de las paredes cambia el aporte de calor.", "source": "p_li2020", "page": 9}, {"text": "El confinamiento puede aumentar o disminuir la inflamabilidad de un sólido según las condiciones; dos muestras de PMMA paralelas forman llamas gemelas con la mayor longitud y tasa de combustión de los escenarios probados.", "source": "p_li2021", "page": 1}, {"text": "Con la misma distancia a los deflectores, una llama que arde por una sola cara del PMMA avanza a poco menos de la mitad de la velocidad de una que arde por ambas caras.", "source": "p_li2021", "page": 1}, {"text": "En flujo opuesto, la propagación disminuye al aumentar el confinamiento, y la velocidad de flujo óptima baja a unos 8,8 cm/s con deflectores a 1 cm, frente a 15 cm/s en el ducto de BASS (3,8 cm de alto).", "source": "p_sharma2024", "page": 11}, {"text": "En flujo opuesto, los deflectores negros dieron llamas sobre SIBAL un 12 % más rápidas que los transparentes, y en PMMA los reflectantes dieron llamas unos 40 % más rápidas que los negros.", "source": "p_sharma2024", "page": 11}], "sources": ["p_li2020", "p_li2021", "p_sharma2024"], "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:Confined Combustion#1', 'confined', 'Confined Combustion', 'finding', 'En flujo concurrente sobre SIBAL existe una distancia mínima entre deflectores (cerca de 1 cm) bajo la cual la llama no avanza, por falta de oxígeno y pérdida de calor hacia las paredes.', 'p_li2020');
INSERT INTO knowledge_chunks VALUES ('psi:Confined Combustion#2', 'confined', 'Confined Combustion', 'finding', 'El confinamiento tiene un efecto no monótono en flujo concurrente: la llama más larga y rápida se dio con una distancia de 4,0 cm entre deflectores; con más confinamiento la llama se debilita.', 'p_li2020');
INSERT INTO knowledge_chunks VALUES ('psi:Confined Combustion#3', 'confined', 'Confined Combustion', 'finding', 'Los deflectores de aluminio pulido dieron las llamas más fuertes y los de policarbonato transparente las más débiles, porque la radiación de las paredes cambia el aporte de calor.', 'p_li2020');
INSERT INTO knowledge_chunks VALUES ('psi:Confined Combustion#4', 'confined', 'Confined Combustion', 'finding', 'El confinamiento puede aumentar o disminuir la inflamabilidad de un sólido según las condiciones; dos muestras de PMMA paralelas forman llamas gemelas con la mayor longitud y tasa de combustión de los escenarios probados.', 'p_li2021');
INSERT INTO knowledge_chunks VALUES ('psi:Confined Combustion#5', 'confined', 'Confined Combustion', 'finding', 'Con la misma distancia a los deflectores, una llama que arde por una sola cara del PMMA avanza a poco menos de la mitad de la velocidad de una que arde por ambas caras.', 'p_li2021');
INSERT INTO knowledge_chunks VALUES ('psi:Confined Combustion#6', 'confined', 'Confined Combustion', 'finding', 'En flujo opuesto, la propagación disminuye al aumentar el confinamiento, y la velocidad de flujo óptima baja a unos 8,8 cm/s con deflectores a 1 cm, frente a 15 cm/s en el ducto de BASS (3,8 cm de alto).', 'p_sharma2024');
INSERT INTO knowledge_chunks VALUES ('psi:Confined Combustion#7', 'confined', 'Confined Combustion', 'finding', 'En flujo opuesto, los deflectores negros dieron llamas sobre SIBAL un 12 % más rápidas que los transparentes, y en PMMA los reflectantes dieron llamas unos 40 % más rápidas que los negros.', 'p_sharma2024');
INSERT INTO investigations VALUES ('scem', 'SCEM', 'Propagación de llama sobre papel filtro en el SCEM del módulo Kibo', 'Internacional', '{"prevencion"}', 4, 'solido', '{"papel filtro (térmicamente delgado)"}', 17.5, 21.1, 'medido', 101.3, 101.3, 'cabina', 0.0, 20.0, 'medido', 0.0, 'ISS (módulo japonés Kibo)', 'Kibo', 'SCEM (JAXA)', '2021-2025', 'no', 'Estudiar la propagación de llama sobre papel filtro térmicamente delgado en microgravedad, especialmente a muy bajo flujo cerca del límite de inflamabilidad.', NULL, '{}', '{"gravity": 0.0, "psi": null, "in_psi": "no", "years": "2021-2025", "pi": null, "variables": null, "diagnostics": [], "id": "scem", "acronym": "SCEM", "name": "Propagación de llama sobre papel filtro en el SCEM del módulo Kibo", "family": "Internacional", "pillars": ["prevencion"], "directness": 4, "directness_reason": "Muestra que los criterios de inflamabilidad convencionales pueden subestimar el riesgo en microgravedad.", "fuel_phase": "solido", "fuels": ["papel filtro (térmicamente delgado)"], "geometry": null, "o2": {"min": 17.5, "max": 21.1, "basis": "medido", "note": "Solo los dos ensayos de la figura 1A (17,5 % y 21,1 %); el rango completo no se revisó (Kobayashi et al. 2026, pág. 7)."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "cabina", "note": "Presión operativa en cámara SCEM del módulo Kibo (101.3 kPa)."}, "flow": {"min": 0.0, "max": 20.0, "basis": "medido", "note": "Flujo opuesto de los dos ensayos de la figura 1A (Kobayashi et al. 2026, pág. 7)."}, "platform": "ISS (módulo japonés Kibo)", "facility": "Kibo", "hardware": "SCEM (JAXA)", "objectives": "Estudiar la propagación de llama sobre papel filtro térmicamente delgado en microgravedad, especialmente a muy bajo flujo cerca del límite de inflamabilidad.", "findings": [{"text": "Se observaron dos modos de propagación: la llama bidimensional convencional y un modo de pequeñas llamas que avanzan en zigzag (flamelet), sobre todo con flujo muy bajo cerca del límite de inflamabilidad.", "source": "p_kobayashi2026", "page": 7}, {"text": "La llama avanzó incluso por debajo de la concentración límite de oxígeno que predice el modelo bidimensional convencional, lo que sugiere que ese criterio puede subestimar la inflamabilidad en microgravedad.", "source": "p_kobayashi2026", "page": 7}, {"text": "La llama bidimensional avanzó típicamente entre 1,0 y 1,5 mm/s con flujos opuestos sobre unos 10-15 cm/s, mientras que el modo flamelet avanzó a menos de 1 mm/s.", "source": "p_kobayashi2026", "page": 7}], "sources": ["p_kobayashi2026"], "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "cabina"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:SCEM#1', 'scem', 'SCEM', 'finding', 'Se observaron dos modos de propagación: la llama bidimensional convencional y un modo de pequeñas llamas que avanzan en zigzag (flamelet), sobre todo con flujo muy bajo cerca del límite de inflamabilidad.', 'p_kobayashi2026');
INSERT INTO knowledge_chunks VALUES ('psi:SCEM#2', 'scem', 'SCEM', 'finding', 'La llama avanzó incluso por debajo de la concentración límite de oxígeno que predice el modelo bidimensional convencional, lo que sugiere que ese criterio puede subestimar la inflamabilidad en microgravedad.', 'p_kobayashi2026');
INSERT INTO knowledge_chunks VALUES ('psi:SCEM#3', 'scem', 'SCEM', 'finding', 'La llama bidimensional avanzó típicamente entre 1,0 y 1,5 mm/s con flujos opuestos sobre unos 10-15 cm/s, mientras que el modo flamelet avanzó a menos de 1 mm/s.', 'p_kobayashi2026');
INSERT INTO investigations VALUES ('wires', 'Cables-PE', 'Propagación de llama sobre aislamiento de cables eléctricos en flujo concurrente', 'Internacional', '{"prevencion"}', 4, 'solido', '{"polietileno (aislamiento de cables de níquel-cromo y de cobre)"}', 18.0, 21.0, 'medido', 101.3, 101.3, 'medido', 5.0, 20.0, 'medido', 0.0, 'Vuelos parabólicos', 'Avión de vuelos parabólicos', NULL, '2018', 'no', 'Determinar si una llama que avanza sobre el aislamiento de un cable en flujo concurrente puede alcanzar una propagación estable en microgravedad.', NULL, '{}', '{"gravity": 0.0, "psi": null, "in_psi": "no", "years": "2018", "pi": null, "variables": null, "diagnostics": [], "id": "wires", "acronym": "Cables-PE", "name": "Propagación de llama sobre aislamiento de cables eléctricos en flujo concurrente", "family": "Internacional", "pillars": ["prevencion"], "directness": 4, "directness_reason": "Los cables eléctricos son una fuente de ignición y combustible típica en una nave.", "fuel_phase": "solido", "fuels": ["polietileno (aislamiento de cables de níquel-cromo y de cobre)"], "geometry": "Cables aislados con polietileno, de núcleo de níquel-cromo o de cobre.", "o2": {"min": 18.0, "max": 21.0, "basis": "medido", "note": "Ensayos a 18% y 21% O2 sobre cables aislados con polietileno (Nagachi et al. 2018, p.14-19)."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "medido", "note": "1 atm (101.3 kPa) reportado en Nagachi et al. 2018, p.7."}, "flow": {"min": 5.0, "max": 20.0, "basis": "medido", "note": "Flujo externo de 50 a 200 mm/s (Nagachi et al. 2018, pág. 3)."}, "platform": "Vuelos parabólicos", "facility": "Avión de vuelos parabólicos", "hardware": null, "objectives": "Determinar si una llama que avanza sobre el aislamiento de un cable en flujo concurrente puede alcanzar una propagación estable en microgravedad.", "findings": [{"text": "En microgravedad, la llama sobre el aislamiento del cable alcanzó una propagación estable incluso en flujo concurrente; en 1 g, con propagación ascendente, no llegó a un estado estable en las condiciones probadas.", "source": "p_nagachi2018", "page": 18}, {"text": "La velocidad de propagación aumentó entre 1 y 1,5 mm/s al subir el flujo concurrente de 6 a 20 cm/s, y fue unos 0,5 mm/s mayor en cables de cobre que en cables de níquel-cromo (con 10 cm/s y 18 % de O2).", "source": "p_nagachi2018", "page": 19}], "sources": ["p_nagachi2018"], "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:Cables-PE#1', 'wires', 'Cables-PE', 'finding', 'En microgravedad, la llama sobre el aislamiento del cable alcanzó una propagación estable incluso en flujo concurrente; en 1 g, con propagación ascendente, no llegó a un estado estable en las condiciones probadas.', 'p_nagachi2018');
INSERT INTO knowledge_chunks VALUES ('psi:Cables-PE#2', 'wires', 'Cables-PE', 'finding', 'La velocidad de propagación aumentó entre 1 y 1,5 mm/s al subir el flujo concurrente de 6 a 20 cm/s, y fue unos 0,5 mm/s mayor en cables de cobre que en cables de níquel-cromo (con 10 cm/s y 18 % de O2).', 'p_nagachi2018');
INSERT INTO investigations VALUES ('olson1987', 'Olson-1987', 'Efecto de la microgravedad en la propagación de llama sobre un combustible delgado', 'Torres de caída', '{"prevencion"}', 3, 'solido', '{"papel de celulosa (Kimwipes, 76 µm y espesor doble)"}', 16.5, 100.0, 'medido', 101.3, 101.3, 'medido', 0.0, 0.0, 'medido', 0.0, 'Torres de caída de NASA Lewis (2,2 s y 5,18 s)', 'Torre de caída', NULL, '1987', 'no', 'Estudiar la propagación de llama sobre un combustible celulósico delgado en microgravedad quieta y compararla con gravedad normal.', 'Concentración de oxígeno, espesor del combustible y gravedad (0 g y 1 g).', '{}', '{"gravity": 0.0, "psi": null, "in_psi": "no", "years": "1987", "pi": "Sandra L. Olson", "variables": "Concentración de oxígeno, espesor del combustible y gravedad (0 g y 1 g).", "diagnostics": [], "id": "olson1987", "acronym": "Olson-1987", "name": "Efecto de la microgravedad en la propagación de llama sobre un combustible delgado", "family": "Torres de caída", "pillars": ["prevencion"], "directness": 3, "directness_reason": "Compara directamente 0 g y 1 g y explica por qué el mecanismo de extinción cambia sin gravedad.", "fuel_phase": "solido", "fuels": ["papel de celulosa (Kimwipes, 76 µm y espesor doble)"], "geometry": "Muestras de 3 cm de ancho y hasta 15 cm de largo.", "o2": {"min": 16.5, "max": 100.0, "basis": "medido", "note": "Desde el límite de extinción (16.5% en 1g / 21% en 0g) hasta 100% O2 (Olson 1987, Tablas A-I a A-IV)."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "medido", "note": "1 atm (Olson 1987, pág. 50)."}, "flow": {"min": 0.0, "max": 0.0, "basis": "medido", "note": "Ambiente quieto (Olson 1987, pág. 50)."}, "platform": "Torres de caída de NASA Lewis (2,2 s y 5,18 s)", "facility": "Torre de caída", "hardware": null, "objectives": "Estudiar la propagación de llama sobre un combustible celulósico delgado en microgravedad quieta y compararla con gravedad normal.", "findings": [{"text": "Con menos oxígeno, el flujo por flotabilidad en 1 g acelera la llama respecto de microgravedad y la mantiene encendida en atmósferas donde en microgravedad quieta se apaga; con mucho oxígeno, la gravedad deja de ser importante.", "source": "p_olson1987", "page": 50}, {"text": "En microgravedad hubo un límite de extinción distinto para cada espesor de combustible, mientras que en 1 g el límite no dependió del espesor.", "source": "p_olson1987", "page": 50}, {"text": "El mecanismo de extinción cambia con la gravedad: en microgravedad la llama se apaga por pérdidas térmicas excesivas, y en 1 g por desprendimiento (blowoff).", "source": "p_olson1987", "page": 50}], "sources": ["p_olson1987"], "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:Olson-1987#1', 'olson1987', 'Olson-1987', 'finding', 'Con menos oxígeno, el flujo por flotabilidad en 1 g acelera la llama respecto de microgravedad y la mantiene encendida en atmósferas donde en microgravedad quieta se apaga; con mucho oxígeno, la gravedad deja de ser importante.', 'p_olson1987');
INSERT INTO knowledge_chunks VALUES ('psi:Olson-1987#2', 'olson1987', 'Olson-1987', 'finding', 'En microgravedad hubo un límite de extinción distinto para cada espesor de combustible, mientras que en 1 g el límite no dependió del espesor.', 'p_olson1987');
INSERT INTO knowledge_chunks VALUES ('psi:Olson-1987#3', 'olson1987', 'Olson-1987', 'finding', 'El mecanismo de extinción cambia con la gravedad: en microgravedad la llama se apaga por pérdidas térmicas excesivas, y en 1 g por desprendimiento (blowoff).', 'p_olson1987');
INSERT INTO investigations VALUES ('pmmarods', 'Varillas-PMMA', 'Propagación de llama sobre varillas delgadas de PMMA', 'Torres de caída', '{"prevencion"}', 2, 'solido', '{"PMMA (varillas de 0,5 y 1 mm de diámetro)"}', 21.0, 40.0, 'medido', 101.3, 101.3, 'medido', 0.0, 25.0, 'medido', 0.0, 'Torre de caída de 2,5 s', 'Torre de caída', NULL, '2022', 'no', 'Comparar la propagación de llama opuesta sobre varillas delgadas de PMMA en gravedad normal y en microgravedad.', 'Diámetro de la varilla, concentración de oxígeno, velocidad del flujo opuesto y gravedad.', '{}', '{"gravity": 0.0, "psi": null, "in_psi": "no", "years": "2022", "pi": "Manu B V, Amit Kumar", "variables": "Diámetro de la varilla, concentración de oxígeno, velocidad del flujo opuesto y gravedad.", "diagnostics": [], "id": "pmmarods", "acronym": "Varillas-PMMA", "name": "Propagación de llama sobre varillas delgadas de PMMA", "family": "Torres de caída", "pillars": ["prevencion"], "directness": 2, "directness_reason": "Compara 0 g y 1 g en varillas delgadas, una geometría parecida a cables; los datos editoriales del manuscrito no están verificados.", "fuel_phase": "solido", "fuels": ["PMMA (varillas de 0,5 y 1 mm de diámetro)"], "geometry": "Varillas de PMMA de 80 mm de largo.", "o2": {"min": 21.0, "max": 40.0, "basis": "medido", "note": "21 %, 23 % y 40 % en ambas gravedades (Manu y Kumar, pág. 8)."}, "pressure": {"min": 101.3, "max": 101.3, "basis": "medido", "note": "1 atm (Manu y Kumar, pág. 1)."}, "flow": {"min": 0.0, "max": 25.0, "basis": "medido", "note": "Flujo opuesto de 0 a 25 cm/s (Manu y Kumar, pág. 1)."}, "platform": "Torre de caída de 2,5 s", "facility": "Torre de caída", "hardware": null, "objectives": "Comparar la propagación de llama opuesta sobre varillas delgadas de PMMA en gravedad normal y en microgravedad.", "findings": [{"text": "Con 21 % y 23 % de O2, la llama avanzó más rápido en microgravedad que en 1 g para ambos diámetros y todos los flujos, porque la zona de precalentamiento es más larga.", "source": "p_manu", "page": 8}, {"text": "La velocidad de propagación disminuyó al aumentar el flujo opuesto en ambas gravedades, y la caída fue más pronunciada en microgravedad.", "source": "p_manu", "page": 8}, {"text": "En microgravedad la llama tomó forma de hongo con el borde de ataque distorsionado, por chorros de combustible que salen de burbujas que revientan en el sólido.", "source": "p_manu", "page": 8}], "sources": ["p_manu"], "pressure_psi": {"min": 14.7, "max": 14.7, "basis": "medido"}}'::jsonb);
INSERT INTO knowledge_chunks VALUES ('psi:Varillas-PMMA#1', 'pmmarods', 'Varillas-PMMA', 'finding', 'Con 21 % y 23 % de O2, la llama avanzó más rápido en microgravedad que en 1 g para ambos diámetros y todos los flujos, porque la zona de precalentamiento es más larga.', 'p_manu');
INSERT INTO knowledge_chunks VALUES ('psi:Varillas-PMMA#2', 'pmmarods', 'Varillas-PMMA', 'finding', 'La velocidad de propagación disminuyó al aumentar el flujo opuesto en ambas gravedades, y la caída fue más pronunciada en microgravedad.', 'p_manu');
INSERT INTO knowledge_chunks VALUES ('psi:Varillas-PMMA#3', 'pmmarods', 'Varillas-PMMA', 'finding', 'En microgravedad la llama tomó forma de hongo con el borde de ataque distorsionado, por chorros de combustible que salen de burbujas que revientan en el sólido.', 'p_manu');
INSERT INTO knowledge_chunks VALUES ('fondo:1', NULL, 'FONDO', 'background', 'Qué es la microgravedad y cómo cambia una llama: Microgravedad es la condición de caída libre en la que no hay flotabilidad: los gases calientes no suben. Por eso las llamas son muy distintas a las de la Tierra: en vez de una gota que parpadea, la llama de una vela se vuelve una esfera azul tenue que obtiene el oxígeno solo por difusión.', 'challenge');
INSERT INTO knowledge_chunks VALUES ('fondo:2', NULL, 'FONDO', 'background', 'Gravedad de la Luna: La gravedad de la Luna es un sexto de la terrestre (aproximadamente 0,17 g). FM2 sería el primer experimento de combustión en otro cuerpo planetario y estudiaría materiales ardiendo a esa gravedad.', 'fm2');
INSERT INTO knowledge_chunks VALUES ('fondo:3', NULL, 'FONDO', 'background', 'Gravedad parcial: qué datos existen: PSI no tiene todavía datos de combustión en gravedad parcial (Luna o Marte). Se espera que se agreguen en el futuro, por ejemplo desde LUCI y FM2. El experimento E-FIELD Flames de ACME imitó la gravedad parcial usando un campo eléctrico que actúa sobre los iones de la llama. Los resultados en microgravedad y en gravedad terrestre podrían acotar lo que ocurre en gravedades intermedias.', 'challenge');
INSERT INTO knowledge_chunks VALUES ('fondo:4', NULL, 'FONDO', 'background', 'Los tres pilares de la seguridad contra incendios de la NASA: La seguridad contra incendios en naves de la NASA se enfoca en prevención, detección y supresión. La prevención se logra controlando las fuentes de ignición y seleccionando materiales, lo que depende de conocer sus límites de inflamabilidad.', 'challenge');
INSERT INTO knowledge_chunks VALUES ('fondo:5', NULL, 'FONDO', 'background', 'Oxígeno y flujo de aire: La inflamabilidad depende fuertemente de la concentración de oxígeno, y en microgravedad el flujo de aire también es importante.', 'challenge');
INSERT INTO knowledge_chunks VALUES ('fondo:6', NULL, 'FONDO', 'background', 'Atmósfera de la base lunar y los rovers presurizados: Para reducir el tiempo de preparación antes de salir con traje, se espera que la base lunar y los rovers presurizados tengan una presión y una concentración de oxígeno intermedias entre las del traje y las de la Tierra: probablemente 30 % de O2 o más, con 10,2 psi o menos. Frente a la atmósfera terrestre es un aumento de más de 40 % en la concentración de oxígeno, lo que hace mucho más inflamables los materiales.', 'challenge');
INSERT INTO knowledge_chunks VALUES ('fondo:7', NULL, 'FONDO', 'background', 'Atmósfera del traje espacial: Los trajes espaciales se llenan con 100 % de oxígeno a solo 4,3 psi, mientras que la presión de la Tierra a nivel del mar es 14,7 psi. Para evitar la enfermedad por descompresión, los astronautas respiran 100 % de oxígeno antes de salir para expulsar el nitrógeno absorbido.', 'challenge');
INSERT INTO knowledge_chunks VALUES ('fondo:8', NULL, 'FONDO', 'background', 'Incendios en la historia de la exploración espacial: En 1967 la tripulación del Apolo 1 murió cuando se desató un incendio en su nave llena de oxígeno durante una prueba previa al lanzamiento. La tripulación del Apolo 13 sufrió la explosión de un tanque de oxígeno camino a la Luna. Una tripulación multinacional sobrevivió a un incendio en la estación Mir causado por la falla de un generador de oxígeno. En la misión Artemis II se activó una alarma de humo durante el vuelo.', 'challenge');
INSERT INTO knowledge_chunks VALUES ('fondo:9', NULL, 'FONDO', 'background', 'Hardware compartido entre investigaciones: Los seis experimentos de ACME usaron llamas de combustibles gaseosos con el mismo hardware modular en el Combustion Integrated Rack (CIR). FLEX, FLEX-2 y CFI quemaron gotas de combustible líquido con el Multi-user Droplet Combustion Apparatus (MDCA) en el CIR. BASS, BASS-II, SPICE y SLICE se hicieron en el Microgravity Science Glovebox (MSG) con el ducto de flujo construido para SPICE.', 'challenge');
INSERT INTO knowledge_chunks VALUES ('fondo:10', NULL, 'FONDO', 'background', 'Ensayos con mayor concentración de oxígeno: Los ensayos en microgravedad con mayor concentración de oxígeno fueron los de CFI-G (ACME). La cámara se llenó con nitrógeno y un gas inflamable como propano, mientras una mezcla de oxígeno y nitrógeno de hasta 85 % de oxígeno salía de un quemador esférico, formando una llama invertida.', 'challenge');
INSERT INTO knowledge_chunks VALUES ('fondo:11', NULL, 'FONDO', 'background', 'Aplicaciones en la Tierra: Los extintores de niebla fina de agua desarrollados para la ISS tienen aplicaciones en la Tierra, y la tecnología de la NASA también mejoró la detección de humo y el equipo de bomberos, incluidos la ropa protectora y los tanques de aire.', 'challenge');
INSERT INTO knowledge_chunks VALUES ('fondo:12', NULL, 'FONDO', 'background', 'Fuera de alcance: cohetes y propelentes: La seguridad contra incendios de cohetes y propelentes queda en general fuera de la investigación disponible en PSI: las altas velocidades dentro de un motor cohete hacen que su combustión sea prácticamente independiente de la gravedad.', 'challenge');
